window.SINUSAL_P2_DADOS={"fontes":[{"id":"p2c","titulo":"P2 · Turma C","sub":"Transcrição de aluno (texto digitado), 20 questões","pags":"79–82","n":20},{"id":"p2d","titulo":"P2 · Turma D","sub":"Folha digitada, 20 questões","pags":"90–95","n":20},{"id":"reg24","titulo":"Segunda prueba de regularización · 2024","sub":"Foto da folha original, Turma C, 7 questões","pags":"5","n":7},{"id":"rec23","titulo":"Segunda prueba recuperatoria · 09/06/2023","sub":"Foto da folha original, 15 questões","pags":"96 e 98","n":15},{"id":"p2f1","titulo":"P2 · foto, questões 9 a 14","sub":"Foto da folha original (página 97, parte de cima)","pags":"97","n":6},{"id":"p2f2","titulo":"P2 · foto, Secciones I a IV","sub":"Foto da folha original (página 97, parte de baixo)","pags":"97","n":8},{"id":"par1","titulo":"1º Parcial · Anatomía Patológica I","sub":"Folha digitada; só as questões de necrose, apoptose e acumulação","pags":"99–103","n":12},{"id":"p1c","titulo":"P1 · Turma C","sub":"Transcrição de aluno; só as questões de necrose, apoptose e acumulação","pags":"83–86","n":14},{"id":"par1r","titulo":"1º Parcial + Recuperación","sub":"Folha digitada; só as questões de necrose, apoptose e acumulação","pags":"87–89","n":14},{"id":"final24","titulo":"Examen Final Complementario · 21/02/2024","sub":"Foto da folha original (págs. 1–4) e transcrição digitada (págs. 104–110); só as questões da P2","pags":"1–4 e 104–110","n":13},{"id":"robbins","titulo":"Banco Robbins · Inflamación","sub":"Prints do banco de questões do Robbins (1 pergunta por página, gabarito \"CORRECTO\" no topo)","pags":"19–58","n":23},{"id":"pef","titulo":"Banco PEF · cap. 3 Inflamación y reparación","sub":"Páginas digitalizadas do livro de perguntas (o X marca a certa). Fora as que ela já copiou: 11, 15, 25 e 27.","pags":"59–78","n":24}],"qs":[{"p":"p2c","n":1,"t":"cita","tema":"pig","q":"Cite 2 pigmentos de hemoglobina:","a":"Bilirrubina y hemosiderina.","e":"Os dois vêm do heme: a hemosiderina guarda o ferro (fica em macrófagos e cora com azul da Prússia) e a bilirrubina é a parte sem ferro (icterícia). Hematoidina também deriva da Hb, mas a dupla que ela espera é essa."},{"p":"p2c","n":2,"t":"cita","tema":"inf","q":"Dos cambios vasculares característicos de la inflamación aguda:","a":"Vasodilatación y aumento de la permeabilidad vascular.","e":"A vasoconstrição arteriolar dura segundos e não é característica (o próprio aluno anotou isso). A estase é consequência dos dois primeiros."},{"p":"p2c","n":3,"t":"cita","tema":"inf","q":"Dos sustancias quimiotácticas endógenas de origen celular:","a":"IL-8 (CXCL8) y leucotrieno B4.","e":"Endógena quer dizer produzida pelo hospedeiro; de origem celular exclui as plasmáticas. Por isso C5a (plasma) e produtos bacterianos (exógenos) não servem. PAF e outras quimiocinas também valeriam. A PGD2 que o aluno citou é quimiotática para eosinófilos, resposta arriscada."},{"p":"p2c","n":4,"t":"comp","tema":"c7","q":"La tinción ________ muestra depósito de material amiloide de color verde manzana al observar al microscopio de luz polarizada.","a":"Rojo Congo.","e":"No microscópio comum o amiloide fica rosa-avermelhado com vermelho Congo; na luz polarizada aparece a birrefringência verde-maçã, por causa da estrutura em folha β-pregueada."},{"p":"p2c","n":5,"t":"comp","tema":"pig","q":"Las llamadas células de insuficiencia cardíaca corresponden a macrófagos alveolares cargados de ________.","a":"Hemosiderina.","e":"Na insuficiência cardíaca esquerda a congestão pulmonar extravasa hemácias para o alvéolo; os macrófagos degradam a Hb e guardam o ferro como hemosiderina. Não é biliverdina nem bilirrubina (pegadinha da Turma D, Q15)."},{"p":"p2c","n":6,"t":"comp","tema":"inf","q":"Se denomina ________ al movimiento de los leucocitos por los tejidos hacia el sitio de lesión por productos bacterianos.","a":"Quimiotaxis.","e":"Locomoção orientada por gradiente químico. Quimiotáticos exógenos: produtos bacterianos. Endógenos: quimiocinas (IL-8), C5a e LTB4."},{"p":"p2c","n":7,"t":"comp","tema":"c7","q":"En el proceso de calcificación patológica, la organela en la que se deposita el calcio es ________.","a":"Mitocondria.","e":"Na calcificação intracelular o cálcio se concentra nas mitocôndrias das células mortas ou morrendo, que perdem o controle do Ca²⁺. No espaço extracelular a nucleação começa em vesículas ligadas à membrana."},{"p":"p2c","n":8,"t":"comp","tema":"c7","q":"En la deficiencia de alfa-1 antitripsina se observan depósitos globulares eosinófilos de una proteína en los hepatocitos; su carencia causa en los pacientes ________.","a":"Enfisema pulmonar.","e":"A AAT mal dobrada fica presa no retículo do hepatócito (glóbulos PAS+ resistentes à diastase) e falta no sangue. Sem ela a elastase dos neutrófilos destrói os alvéolos: enfisema panacinar. No fígado o acúmulo causa hepatite e cirrose."},{"p":"p2c","n":9,"t":"cita","tema":"pig","q":"Una paciente de 4 años… [enunciado cortado en la transcripción]","a":"Polvo de carbón (antracosis).","e":"Antracose é o pigmento exógeno mais comum: o carvão inalado é captado pelos macrófagos alveolares e levado aos linfonodos traqueobrônquicos.","nt":"A transcrição só guardou o começo do caso. A resposta anotada (pó de carvão) mostra que era a questão de pigmento exógeno."},{"p":"p2c","n":10,"t":"cita","tema":"c7","q":"Mujer sana de 73 años cae por las escaleras y se lesiona la cadera derecha. No hay fractura, pero la radiografía revela calcificación de las pequeñas arterias musculares laterales al útero.","a":"Esclerosis medial calcificada (de Mönckeberg), que es una calcificación distrófica.","e":"Idosa saudável, sem hipercalcemia, com cálcio na camada média de artérias musculares: é Mönckeberg, uma forma de calcificação distrófica. Responder \"metastásica\" é o erro clássico, porque metastásica exige hipercalcemia.","nt":"Quando ela dá o quadro de opções (P2 da p. 97, Q3) a resposta esperada é literalmente \"Esclerosis medial calcificada\"."},{"p":"p2c","n":11,"t":"cita","tema":"c7","q":"¿Cuál de los siguientes depósitos corresponde a una calcificación distrófica?","a":"Cuerpos de psamoma.","e":"Psamoma é calcificação distrófica em lâminas concêntricas sobre papilas necrosadas: carcinoma papilar de tireoide, cistoadenocarcinoma seroso de ovário, meningioma e mesotelioma.","nt":"A transcrição só guardou a alternativa marcada."},{"p":"p2c","n":12,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la opción correcta:","o":["C5b-9 – opsonización","TNF – fiebre","Leucotrieno C4 – vasodilatación","Prostaciclina – aumento de la permeabilidad"],"ok":[1],"w":["C5b-9 é o complexo de ataque à membrana, que faz lise. Quem opsoniza é o C3b.","IL-1 e TNF são os pirógenos endógenos: induzem COX-2 e PGE2 no hipotálamo.","LTC4, D4 e E4 causam vasoconstrição, broncoespasmo e aumento de permeabilidade. Não são vasodilatadores.","Prostaciclina (PGI2) é vasodilatadora e antiagregante; o efeito principal não é permeabilidade."]},{"p":"p2c","n":13,"t":"cita","tema":"c7","q":"El término hialino corresponde a:","a":"Alteración en las células o en el espacio extracelular que da un aspecto homogéneo, vítreo y rosado en los cortes histológicos con H&E.","e":"É um termo descritivo, não uma substância. Intracelular: corpos de Russell, hialina de Mallory, gotas de reabsorção no túbulo proximal. Extracelular: arteriolosclerose hialina, amiloide, colágeno de cicatriz antiga."},{"p":"p2c","n":14,"t":"mc","tema":"inf","q":"En los siguientes pasos presentes en el reclutamiento de los leucocitos, ¿cuál de ellos se encuentra en orden secuencial?","o":["Transmigración, adhesión, fagocitosis","Marginación, adhesión, rodamiento","Rodamiento, adhesión, diapédesis","Migración, adhesión, transmigración"],"ok":[2],"w":["A adesão vem antes da transmigração.","O rolamento vem antes da adesão firme.","Ordem certa: marginação, rolamento (selectinas), adesão (integrinas), diapedese (PECAM-1) e quimiotaxia.","A migração no tecido é o último passo, não o primeiro."]},{"p":"p2c","n":15,"t":"mc","tema":"pig","q":"Con respecto a la neumoconiosis [antracosis] es correcto afirmar que (tiene dos respuestas correctas):","o":["Se observa en los pulmones de casi todos los adultos","Es más pronunciada en pacientes fumadores","No suele provocar ninguna reacción de lesión tisular","La exposición prolongada a partículas orgánicas e inorgánicas casi siempre se produce en lugar del tabaco"],"ok":[0,1],"w":["O carvão é poluente onipresente; a antracose aparece no pulmão de quase todo adulto urbano.","Fumantes acumulam mais pigmento.","Em geral é inócua, mas em grande quantidade induz reação fibroblástica e enfisema (pneumoconiose do mineiro). \"Ninguna reacción\" é absoluto demais.","Frase truncada na transcrição; como está, não tem sentido técnico."],"nt":"Transcrição confusa, misturando português. O tema real é antracose (pigmento exógeno); a dupla a + b é a mais defensável, mas não tenho a folha original."},{"p":"p2c","n":16,"t":"mc","tema":"inf","q":"Se realiza una toracocentesis de la cavidad pleural izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un exudado?","o":["Alto contenido de proteínas","Aspecto claro, seroso","Recuento bajo de leucocitos","Baja densidad"],"ok":[0],"w":["Exsudato nasce do aumento de permeabilidade: proteína alta, densidade acima de 1,020, células e restos.","Claro e seroso sugere transudato.","Poucas células é transudato.","Densidade baixa (abaixo de 1,012) é transudato."]},{"p":"p2c","n":17,"t":"mc","tema":"inf","q":"Un grupo de pacientes recibe un inhibidor de la ciclooxigenasa 2 (COX-2). Los hombres adultos tenían insuficiencia cardíaca y artritis de pequeñas articulaciones. Refieren que el fármaco ha presentado ciertos efectos. ¿Cuál de los siguientes hallazgos es más probable que refiera el grupo que recibió el fármaco?","o":["Reducción del dolor articular","Numerosos episodios febriles","Mayor tumefacción de los tobillos"],"ok":[0],"w":["A COX-2 produz PGE2, que sensibiliza os nociceptores. Inibir a COX-2 reduz a dor.","A febre também depende de PGE2; o inibidor reduz a febre, não aumenta.","Retenção de sódio e edema podem ocorrer com coxibes, mas a questão (copiada do PEF, Q15) quer o efeito anti-inflamatório típico: menos dor."],"nt":"A transcrição cortou a 3ª alternativa; completei pelo Examen Final, que repete a mesma questão."},{"p":"p2c","n":18,"t":"mc","tema":"inf","q":"Una mujer de 58 años ha tenido tos con fiebre durante 3 días. Una radiografía de tórax revela infiltrados en el lóbulo inferior derecho. En un cultivo de esputo crece Streptococcus pneumoniae. La eliminación de estos organismos del parénquima pulmonar se lograría de manera más efectiva mediante la generación de ¿cuál de las siguientes sustancias por el principal tipo de célula inflamatoria que responde a esta infección?","o":["Prostaglandina E2","Calicreína","Leucotrieno B4","Peróxido de hidrógeno"],"ok":[3],"w":["PGE2 causa vasodilatação, dor e febre; não mata bactéria.","A calicreína gera bradicinina (dor e permeabilidade).","LTB4 é quimiotático: atrai o neutrófilo, mas não mata.","O neutrófilo (célula principal na pneumonia bacteriana) gera H2O2 pela NADPH oxidase, e a mieloperoxidase o converte em HOCl. O sistema H2O2-MPO-haleto é o bactericida mais eficiente."],"nt":"Copiada do Robbins (banco, Pregunta 4)."},{"p":"p2c","n":19,"t":"mc","tema":"inf","q":"Una niña de 4 años ha presentado numerosas infecciones por Staphylococcus aureus desde la lactancia. Las pruebas genéticas muestran un defecto causante de la ausencia de producción de β2-integrinas. ¿Cuál de las siguientes alteraciones es más probable que ocurra por deficiencia de β2-integrina?","o":["Menor producción de radicales libres (ERO)","Adhesión neutrofílica inadecuada al endotelio","Reducción de la fagocitosis de bacterias opsonizadas","Fracaso del proceso en el cual los leucocitos se colocan sobre el endotelio de forma transitoria"],"ok":[1],"w":["Os radicais vêm da NADPH oxidase; o defeito dela é a doença granulomatosa crônica.","As β2-integrinas (LFA-1 e Mac-1) fazem a adesão firme ao ICAM-1. É a deficiência de adesão leucocitária tipo 1.","Mac-1 também é receptor de iC3b, então a fagocitose cai um pouco, mas o defeito cobrado é a adesão.","Pousar no endotélio de forma transitória é o rolamento, feito pelas selectinas (deficiência de adesão tipo 2)."],"nt":"Repete na P2 da p. 97 (Q12) e no PEF (Q11)."},{"p":"p2c","n":20,"t":"mc","tema":"inf","q":"Un hombre de 37 años ha tenido náuseas y vómitos durante 5 semanas. Ayer experimentó un episodio de hematemesis. En el examen físico no presenta hallazgos anormales. Se realiza una endoscopia del tracto gastrointestinal superior y se observa una lesión de 1,5 cm de diámetro en el antro gástrico con pérdida de la superficie epitelial. ¿Estos hallazgos son más típicos de cuál de los siguientes procesos patológicos?","o":["Absceso","Granuloma","Gangrena","Úlcera"],"ok":[3],"w":["Abscesso é coleção de pus dentro do tecido, não perda de superfície.","Granuloma é agregado de macrófagos epitelioides (inflamação crônica).","Gangrena é necrose de um membro ou segmento.","Úlcera é a perda local do epitélio de superfície com tecido necrótico inflamado."],"nt":"Copiada do Robbins (banco, Pregunta 16)."},{"p":"p2d","n":1,"t":"cita","tema":"c7","q":"Cita dos patologías que cursan con depósitos de amiloide.","a":"Por ejemplo: mieloma múltiple (AL) y artritis reumatoide (AA). También valen Alzheimer (Aβ), amiloidosis senil (transtiretina), túnel carpiano por hemodiálisis (β2-microglobulina), carcinoma medular de tiroides (calcitonina), colitis ulcerosa/Crohn (AA).","e":"Duas armadilhas na lista do aluno. Parkinson não entra: não está na tabela de amiloidoses do Robbins (o depósito é α-sinucleína, corpos de Lewy). E o \"tumor de tiroides\" tem de ser o carcinoma MEDULAR; o papilar dá psamoma, não amiloide."},{"p":"p2d","n":2,"t":"cita","tema":"pig","q":"Cita pigmentos endógenos que no causan daño a la célula.","a":"Melanina y lipofuscina.","e":"A lipofuscina é o pigmento do desgaste (lipídio peroxidado): marca dano antigo por radicais livres, mas por si só não lesa a célula. A melanina é normal. Hemosiderina em excesso (hemocromatose) já causa dano."},{"p":"p2d","n":3,"t":"cita","tema":"inf","q":"Cite signos cardinales de inflamación resultantes de la vasodilatación.","a":"Rubor y calor.","e":"Mais sangue no local deixa vermelho e quente. Tumor vem do aumento de permeabilidade (edema), dor das PG e da bradicinina."},{"p":"p2d","n":4,"t":"comp","tema":"c7","q":"Paciente masculino de 65 años consulta por palpitaciones. El ecocardiograma informa aurícula izquierda agrandada con área valvular mitral de 1 cm (reducida), en donde se constata calcificación de tipo ________.","a":"Distrófica.","e":"Válvula lesada com cálcio sérico normal é distrófica. Metastásica exigiria hipercalcemia e atinge tecidos normais (rim, pulmão, mucosa gástrica)."},{"p":"p2d","n":5,"t":"comp","tema":"inf","q":"La ________ es el principal mediador de las fases transitoria inmediata de la inflamación, causante de vasodilatación y aumento de permeabilidad vascular.","a":"Histamina.","e":"Está pré-formada nos grânulos do mastócito e sai em segundos. Age no receptor H1 das vênulas e contrai o endotélio: resposta transitória imediata, de 15 a 30 min."},{"p":"p2d","n":6,"t":"comp","tema":"c7","q":"Se denomina hialina de Mallory a la acumulación de ________ en células hepáticas relacionadas con el consumo de alcohol.","a":"Filamentos intermedios de queratina (citoqueratinas 8 y 18).","e":"Inclusões eosinófilas e ubiquitinadas no citoplasma do hepatócito (corpos de Mallory-Denk). Típicas da hepatite alcoólica, mas também aparecem em esteato-hepatite não alcoólica e Wilson."},{"p":"p2d","n":7,"t":"comp","tema":"inf","q":"En la inflamación aguda, la migración de leucocitos ocurre principalmente a través del endotelio de las ________.","a":"Vénulas poscapilares.","e":"É ali que a histamina age e que há mais selectinas e ICAM. Pegadinha das outras provas: \"vénulas precapilares\" não existe nesse contexto."},{"p":"p2d","n":8,"t":"cita","tema":"inf","q":"Moléculas de adhesión, expresadas en las células endoteliales, importantes para el proceso en el cual los leucocitos de forma individual y en filas se colocan sobre el endotelio de forma transitoria.","a":"E-selectina.","e":"Pousar de forma transitória é o rolamento, mediado por selectinas (E e P no endotélio). A \"familia de inmunoglobulinas\" (ICAM-1, VCAM-1) é da adesão firme. \"Marginación\" é o processo, não a molécula.","nt":"Seção com quadro de opções: Peroxidación de los lípidos de la membrana · Metabolitos del ácido araquidónico · Desoxihemoglobina · Familia de inmunoglobulinas · Complejo de ataque a membrana · E-selectina · Sistema del complemento · Productos de degradación de hemoglobina · Marginación."},{"p":"p2d","n":9,"t":"cita","tema":"inf","q":"Las bacterias son fagocitadas por neutrófilos o sufren lisis, efectos que son facilitados por componentes del plasma sanguíneo:","a":"Sistema del complemento.","e":"A pergunta junta fagocitose (opsonização por C3b) e lise (C5b-9). O componente que faz as duas coisas é o sistema do complemento.","nt":"O aluno respondeu \"Complejo de ataque de membrana\", que só cobre a lise. O Examen Final (Q10) e o PEF (Q19) dão \"complemento\"."},{"p":"p2d","n":10,"t":"cita","tema":"pig","q":"Una mujer de 22 años tiene anemia congénita y ha recibido transfusiones durante muchos años. Ahora tiene un color bronce más oscuro en la piel por depósito de sustancias:","a":"Productos de degradación de la hemoglobina (hemosiderina).","e":"Transfusões repetidas mais hemólise sobrecarregam de ferro: hemossiderose sistêmica, hemocromatose secundária. A desoxi-hemoglobina dá cianose, não depósito."},{"p":"p2d","n":11,"t":"mc","tema":"c7","q":"¿Cuál de las siguientes alteraciones es posible encontrar en los cuerpos de psamoma?","o":["Ateromas de aterosclerosis avanzada","Válvulas cardíacas de ancianos","Ganglios linfáticos tuberculosos","Carcinoma papilar de tiroides"],"ok":[3],"w":["O ateroma avançado tem calcificação distrófica, mas amorfa, sem lâminas concêntricas.","Válvula senil tem calcificação distrófica grosseira, sem psamoma.","Linfonodo tuberculoso calcifica sobre a necrose caseosa, sem psamoma.","Psamoma é calcificação distrófica lamelar em papilas: carcinoma papilar de tireoide, cistoadenocarcinoma seroso de ovário, meningioma."],"nt":"As quatro são calcificação distrófica; só a d forma psamoma."},{"p":"p2d","n":12,"t":"mc","tema":"inf","q":"La pericarditis en \"pan con mantequilla\" es un ejemplo típico de inflamación de tipo:","o":["Serosa","Fibrinosa","Supurativa","Ulcerativa"],"ok":[1],"w":["Serosa é líquido pobre em proteína e células (bolha, derrame).","Fibrina depositada entre os folhetos: ao separá-los parece pão com manteiga. Típica de febre reumática, uremia e pós-infarto.","Supurativa é pus: neutrófilos e necrose liquefativa.","Ulcerativa é perda de epitélio de superfície, não exsudato em serosa."]},{"p":"p2d","n":13,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la alternativa correcta:","o":["Leucotrieno B4 – vasodilatación","Interleucina 6 – dolor","C3b – opsonización","Prostaciclina – aumento de la permeabilidad"],"ok":[2],"w":["LTB4 é quimiotático e ativa neutrófilos.","IL-6 dá febre e proteínas de fase aguda (PCR). Dor é PG e bradicinina.","O C3b recobre o micróbio e é reconhecido pelo receptor CR1 do fagócito.","Prostaciclina é vasodilatadora e antiagregante."]},{"p":"p2d","n":14,"t":"mc","tema":"c7","q":"Con respecto al depósito de material amiloide es correcto afirmar que:","o":["La tinción usada comúnmente para su visualización es rojo Congo","Las sustancias insolubles se depositan en el citoplasma de las células","La amiloidosis […] es la forma más frecuente de la amiloidosis senil","En la amiloidosis secundaria se acumulan amiloides de cadena ligera de las células plasmáticas"],"ok":[0],"w":["Vermelho Congo é a coloração de rotina para amiloide.","Amiloide é sempre EXTRACELULAR, entre as células e em volta dos vasos.","Palavra cortada na transcrição. A amiloidose senil sistêmica é de transtirretina normal e atinge sobretudo o coração; se a alternativa trazia outro tipo, estava errada. A resposta segura é a a.","Cadeia leve (AL) é a amiloidose primária, de plasmócitos. A secundária (reativa) é AA, vinda da SAA do fígado na inflamação crônica."]},{"p":"p2d","n":15,"t":"mc","tema":"pig","q":"Analiza los siguientes enunciados sobre acumulación intracelular de pigmentos. 1. Para confirmar los depósitos de hemosiderina se utiliza la tinción azul de Prusia. 2. Las células de insuficiencia cardíaca corresponden a macrófagos alveolares cargados de biliverdina. 3. El pigmento de lipocromo es un indicador de lesión por radicales libres y peroxidación lipídica. 4. La antracosis se produce por exposición prolongada a sustancias inhaladas, como el carbón, e induce una reacción fibroblástica en los pulmones. De estas, ¿cuáles corresponden a respuestas correctas?","o":["1 y 3","1 y 4","2 y 3","3 y 4"],"ok":[0],"w":["1 é verdadeira (azul da Prússia ou Perls cora ferro). 3 é verdadeira (lipocromo é a lipofuscina, marcador de peroxidação lipídica).","A 4 generaliza: a antracose comum é inócua; reação fibroblástica só com grande acúmulo (pneumoconiose do mineiro).","A 2 é falsa: as células da insuficiência cardíaca têm hemosiderina, não biliverdina.","A 4 é a frase que generaliza (ver b)."]},{"p":"p2d","n":16,"t":"mc","tema":"c7","q":"Los cuerpos de Russell en las células plasmáticas del bazo de un hombre de 60 años están llenos de:","o":["Transtiretina","AAT (α1-antitripsina)","Inmunoglobulina","β2-microglobulina"],"ok":[2],"w":["Transtirretina é a amiloidose senil e a familiar.","A AAT forma glóbulos no hepatócito, não no plasmócito.","Corpos de Russell são imunoglobulina recém-sintetizada acumulada no RE rugoso do plasmócito: inclusões redondas, homogêneas e eosinófilas.","β2-microglobulina é o amiloide da hemodiálise."]},{"p":"p2d","n":17,"t":"mc","tema":"inf","q":"En la toracocentesis realizada en la cavidad pleural izquierda se obtiene un líquido amarillento y turbio que tiene un recuento de leucocitos aumentado con predominio de neutrófilos. La tinción de Gram muestra cocos Gram +. ¿Cuál de los siguientes términos describe el proceso?","o":["Exudado fibrinoso","Ultrafiltrado de plasma","Organización y cicatrización","Exudado purulento"],"ok":[3],"w":["Fibrinoso é fibrina sobre a serosa, sem pus.","Ultrafiltrado de plasma é transudato: claro e pobre em células.","Organização é a fase de reparo (tecido de granulação, fibrose).","Turvo, cheio de neutrófilos e com cocos piogênicos é pus; na pleura se chama empiema."],"nt":"Copiada do PEF (Q23)."},{"p":"p2d","n":18,"t":"mc","tema":"inf","q":"Hombre de 25 años presenta disnea progresiva en las últimas horas; mediante una toracocentesis se obtienen 200 ml de un líquido amarillo ligeramente turbio en la cavidad pleural derecha. El examen citológico del líquido revela múltiples neutrófilos. ¿Cuál de los siguientes mecanismos contribuye a la acumulación de este líquido pleural?","o":["Vasoconstricción arteriolar","Contracción endotelial","Obstrucción linfática","Liberación de los lisosomas por los neutrófilos"],"ok":[1],"w":["A vasoconstrição é transitória e reduz o fluxo; não forma exsudato.","Mecanismo mais comum do aumento de permeabilidade: histamina, bradicinina e LTs contraem o endotélio das vênulas e abrem fendas.","Obstrução linfática dá linfedema; aqui há neutrófilos, então é exsudato inflamatório.","Enzimas lisossômicas lesam o tecido, mas não são o mecanismo principal do acúmulo de líquido."],"nt":"Copiada do PEF (Q5)."},{"p":"p2d","n":19,"t":"mc","tema":"inf","q":"Hombre de 22 años desarrolla dolor abdominal marcado en el cuadrante inferior derecho. Se realiza una cirugía laparoscópica y el apéndice está hinchado, eritematoso, parcialmente cubierto por exudado amarillento. ¿Cuál de los siguientes mediadores químicos es causante del dolor que experimenta el paciente?","o":["Complemento C3b e inmunoglobulina G","IL-1 y TNF","Prostaglandinas y bradicinina","Leucotrienos y HPETE"],"ok":[2],"w":["C3b e IgG são opsoninas.","IL-1 e TNF dão febre e resposta de fase aguda.","A PGE2 sensibiliza as terminações nervosas à bradicinina: dor.","Leucotrienos dão broncoespasmo, permeabilidade e quimiotaxia; HPETE é intermediário da lipoxigenase."],"nt":"Copiada do Robbins (banco, Pregunta 1)."},{"p":"p2d","n":20,"t":"mc","tema":"c7","q":"Paciente masculino de 65 años, conocido portador de enfermedad renal crónica, con diálisis 3 veces por semana, acude a la consulta por dolor en la mano izquierda. Se evidencian depósitos de calcio en las articulaciones carpometacarpianas. En la prueba de laboratorio muestra una calcemia de 15,4 (valores normales […]).","o":["Calcificación metastásica","Calcificación idiopática","Calcificación distrófica","Calcificación senil"],"ok":[0],"w":["Hipercalcemia (renal crônico: hiperparatireoidismo secundário e retenção de fosfato) com cálcio em tecido normal é metastásica.","\"Idiopática\" não é categoria de calcificação patológica no Robbins.","Distrófica ocorre com cálcio normal, em tecido morto ou lesado.","\"Senil\" não é categoria; a calcificação valvar do idoso é distrófica."]},{"p":"reg24","n":1,"t":"cita","tema":"c7","q":"2 patologías que presentan una amiloidosis sistémica reactiva (secundaria):","a":"Artritis reumatoide y enfermedad de Crohn o colitis ulcerosa (también tuberculosis, bronquiectasias, osteomielitis crónica).","e":"Reativa é a AA: inflamação crônica, IL-6 e IL-1, SAA produzida pelo fígado. O aluno respondeu Crohn e colite ulcerosa, ambas certas. Mieloma não serve: é AL, primária."},{"p":"reg24","n":2,"t":"cita","tema":"inf","q":"2 mediadores químicos que causan aumento de la permeabilidad vascular:","a":"Histamina y bradicinina (también LTC4, LTD4, LTE4).","e":"Resposta do aluno correta. C3a e C5a aumentam a permeabilidade indiretamente, liberando histamina."},{"p":"reg24","n":3,"t":"cita","tema":"inf","q":"2 fagocitos principales presentes en la reacción inflamatoria aguda:","a":"Neutrófilos y macrófagos.","e":"O aluno riscou \"mastocitos\" e fez bem: mastócito não é fagócito, ele libera histamina."},{"p":"reg24","n":4,"t":"comp","tema":"c7","q":"Paciente masculino de 65 años consulta por palpitaciones, el ecocardiograma informa aurícula izquierda agrandada con área valvular mitral de 1 cm (reducida), en donde se constata calcificación de tipo ________.","a":"Distrófica.","e":"Mesma questão da P2 Turma D (Q4): válvula lesada e cálcio normal."},{"p":"reg24","n":5,"t":"comp","tema":"inf","q":"La ________ es el principal mediador de la fase transitoria inmediata de la inflamación, causante de dilatación arteriolar y aumento de permeabilidad venular.","a":"Histamina.","e":"Repetida da Turma D (Q5)."},{"p":"reg24","n":6,"t":"comp","tema":"c7","q":"Los cuerpos de Russell en las células plasmáticas del bazo de un hombre de 60 años están cargados de ________.","a":"Inmunoglobulinas.","e":"Na Turma D a mesma pergunta veio de múltipla escolha (Q16)."},{"p":"reg24","n":7,"t":"comp","tema":"inf","q":"La pericarditis \"en pan con mantequilla\" es un ejemplo típico de inflamación aguda tipo ________.","a":"Fibrinosa.","e":"Caiu nas três provas de P2 que temos."},{"p":"rec23","n":1,"t":"mc","tema":"inf","q":"Paciente femenina de 25 años de edad que, cocinando los alimentos en su casa, sufre quemaduras de la mano con presencia posteriormente de ampollas a ese nivel. ¿Qué tipo de inflamación presentaría y cuál sería la característica de la extravasación?","o":["Inflamación serosa; líquido con bajo contenido de células","Inflamación fibrinosa; líquido con red eosinófila de fibrina","Absceso; líquido con alto contenido de neutrófilos","Inflamación supurativa; líquido con elevada concentración de proteínas"],"ok":[0],"w":["Bolha de queimadura é inflamação serosa: líquido pobre em células, vindo do plasma.","Fibrinosa exige permeabilidade maior e aparece em cavidades (pericárdio, pleura), não em bolha.","Abscesso é pus localizado por infecção piogênica.","Supurativa é pus. A proteína alta é de qualquer exsudato; o que define o pus são neutrófilos e necrose."]},{"p":"rec23","n":2,"t":"mc","tema":"inf","q":"Paciente de 20 años de edad que hace 2 días presenta fiebre elevada, dolor en fosas lumbares y ardor al orinar; en el examen de orina se encuentran leucocitos abundantes. En la respuesta inflamatoria, de los siguientes procesos, ¿cuál se produce más tardíamente?","o":["Liberación de histamina por degranulación de mastocitos","Vasodilatación y estasis sanguínea","Migración de monocitos","Extravasación de líquido al espacio intersticial"],"ok":[2],"w":["A histamina sai em segundos: é o primeiro evento.","Vasodilatação e estase acontecem em minutos a poucas horas.","Neutrófilos predominam nas primeiras 6 a 24 h; monócitos e macrófagos os substituem entre 24 e 48 h.","A exsudação vem cedo, junto com o aumento de permeabilidade."]},{"p":"rec23","n":3,"t":"mc","tema":"inf","q":"Paciente de 18 años de edad, femenina, con el antecedente de padecer una fiebre reumática y que ahora presenta fiebre, soplo cardíaco y un roce pericárdico; se le diagnostica una pericarditis \"en pan y manteca\", que es un ejemplo típico de inflamación de tipo:","o":["Serosa","Fibrinosa","Supurativa","Ulcerativa"],"ok":[1],"w":["Serosa é líquido pobre em células e proteína.","Fibrina entre os folhetos do pericárdio, como pão com manteiga. Febre reumática é causa clássica.","Supurativa é pus.","Ulcerativa é perda de epitélio de superfície."]},{"p":"rec23","n":4,"t":"mc","tema":"inf","q":"Paciente de 38 años de edad, masculino, fumador, presenta dolor en epigastrio y acidez. Se le realiza una gastroscopia y se observa lesión ulcerada en el antro gástrico. ¿Qué mediadores químicos estarían implicados en la producción del dolor?","o":["Anafilotoxinas","Leucotrieno B4","Opsoninas","Bradicinina"],"ok":[3],"w":["C3a e C5a liberam histamina (permeabilidade); C5a também atrai leucócitos.","LTB4 é quimiotático.","Opsoninas (C3b, IgG) facilitam a fagocitose.","Bradicinina, junto com a PGE2, estimula as terminações nervosas da dor."]},{"p":"rec23","n":5,"t":"mc","tema":"cro","q":"Se pueden observar células gigantes multinucleadas en todos los siguientes procesos inflamatorios, excepto:","o":["Tuberculosis","Sarcoidosis","Leishmaniasis","Cuerpos extraños"],"ok":[2],"w":["TB tem granuloma caseoso com células de Langhans. O aluno marcou esta, e errou.","Sarcoidose tem granuloma não caseoso com células gigantes.","É a única fora da lista de doenças granulomatosas do Robbins; o achado típico são macrófagos cheios de amastigotas. Ressalva: formas crônicas podem formar granuloma, então é a \"menos típica\", não um \"nunca\".","Corpo estranho tem células gigantes do tipo corpo estranho em volta do material."],"nt":"Inflamação crônica e granulomatosa, fora dos slides da P2 atual. Gabarito com ressalva."},{"p":"rec23","n":6,"t":"mc","tema":"inf","q":"Paciente femenina de 40 años de edad que, con antecedentes de una sinusitis aguda mal tratada, hace un absceso cerebral como complicación. En la complicación inflamatoria observada generalmente no se observará:","o":["Vasodilatación y vasocongestión","Presencia de leucotrieno B4","Infiltrado linfoplasmocitario","Residuos licuados de células necróticas"],"ok":[2],"w":["Abscesso é inflamação aguda: há vasodilatação e congestão.","LTB4 atrai neutrófilos, então está presente. O aluno marcou esta, e errou.","Linfócitos e plasmócitos são da inflamação crônica; no abscesso agudo predominam neutrófilos.","Abscesso é necrose liquefativa: os restos liquefeitos estão lá."]},{"p":"rec23","n":7,"t":"vf","tema":"inf","q":"La inhibición selectiva de la vía de la ciclooxigenasa en el metabolismo del ácido araquidónico influirá negativamente en la formación de leucotrienos y prostaglandinas.","ok":false,"e":"A COX produz prostaglandinas e tromboxano. Leucotrienos vêm da 5-lipoxigenase, então inibir a COX não os reduz (pode até desviar substrato para eles, como na asma por aspirina)."},{"p":"rec23","n":8,"t":"vf","tema":"inf","q":"El fenómeno de migración es un proceso de redistribución leucocitaria, por el cual los leucocitos se sitúan en la periferia del flujo sanguíneo.","ok":false,"e":"Isso é marginação. Migração (transmigração) é atravessar o endotélio."},{"p":"rec23","n":9,"t":"vf","tema":"inf","q":"La forma en que inicialmente aumenta la permeabilidad vascular es por la contracción de células endoteliales, que determinan el incremento de los espacios interendoteliales.","ok":true,"e":"É o mecanismo mais comum e mais precoce: histamina, bradicinina e leucotrienos, nas vênulas pós-capilares, durando 15 a 30 min."},{"p":"rec23","n":10,"t":"vf","tema":"inf","q":"Cuando la sangre circula por el lecho capilar, se puede distinguir un flujo central y un flujo periférico. En condiciones normales, el flujo central contiene leucocitos y eritrocitos.","ok":true,"e":"No fluxo laminar normal as células ficam na coluna axial e o plasma na periferia. Com a estase os leucócitos vão para a periferia (marginação)."},{"p":"rec23","n":11,"t":"cita","tema":"inf","q":"3 manifestaciones locales de inflamación conocidas como signos cardinales:","a":"Rubor, calor y tumor (también dolor y pérdida de función).","e":"Celso descreveu rubor, tumor, calor e dor; Virchow acrescentou a functio laesa."},{"p":"rec23","n":12,"t":"cita","tema":"inf","q":"2 mediadores químicos de inflamación derivados del plasma:","a":"Complemento (anafilotoxinas C3a y C5a) y cininas (bradicinina). También el sistema de coagulación (trombina).","e":"Os plasmáticos circulam como precursores inativos feitos no fígado. Histamina, prostaglandinas, leucotrienos e citocinas são de origem celular."},{"p":"rec23","n":13,"t":"comp","tema":"cro","q":"Las células gigantes multinucleadas derivan de la activación de ________.","a":"Macrófagos.","e":"Fusão de macrófagos ativados por IFN-γ, no granuloma.","nt":"Inflamação crônica, fora dos slides atuais."},{"p":"rec23","n":14,"t":"comp","tema":"inf","q":"El principal mediador en el edema producido por una reacción alérgica aguda es ________.","a":"Histamina.","e":"O aluno escreveu \"mastocitos\": é a célula, não o mediador. Erro clássico que tira o ponto."},{"p":"rec23","n":15,"t":"comp","tema":"cro","q":"La presencia de ________ son condiciones para la formación de un granuloma.","a":"Un agente difícil de erradicar (persistente) y una respuesta inmune mediada por linfocitos T.","e":"O granuloma tenta conter um agente que não se elimina (micobactéria, fungo, corpo estranho) e é mantido por Th1 e IFN-γ.","nt":"Inflamação crônica, fora dos slides atuais."},{"p":"p2f1","n":9,"t":"mc","tema":"pig","q":"Con respecto a la antracosis es correcto afirmar que:","o":["Están relacionadas a enfermedades pulmonares ocupacionales","Puede inducir una reacción fibroblástica en los pulmones","Se debe a la inhalación de sustancias orgánicas e inorgánicas como la sílice y el carbón","El polvo de carbón es captado por macrófagos alveolares y transportado en ganglios linfáticos traqueobronquiales"],"ok":[3],"w":["A antracose em si é achado comum e inócuo de quem vive na cidade; doença ocupacional é a pneumoconiose do mineiro, a forma grave.","Só é verdade com grande acúmulo (pneumoconiose). Como afirmação sobre a antracose em geral, fica incompleta.","Antracose é só carvão. Sílica causa silicose.","É a descrição do Robbins: macrófagos alveolares captam o carvão e o levam aos linfonodos traqueobrônquicos, que ficam pretos."],"nt":"A b aparece como afirmação na Turma D (Q15, item 4). A d é a única sem ressalva."},{"p":"p2f1","n":10,"t":"mc","tema":"inf","q":"¿Cuál de los siguientes procesos se presenta más tempranamente en la inflamación aguda?","o":["Adhesión neutrofílica","Incremento de la permeabilidad vascular","Formación de edema inflamatorio","Destrucción tisular"],"ok":[1],"w":["A adesão vem depois das alterações vasculares e da ativação do endotélio.","As alterações vasculares (vasodilatação e aumento de permeabilidade) são o primeiro evento; das opções, é a mais precoce.","O edema é consequência do aumento de permeabilidade.","A destruição do tecido por enzimas e radicais é tardia."]},{"p":"p2f1","n":11,"t":"mc","tema":"inf","q":"Se realiza una toracocentesis de la cavidad pleural izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un exudado?","o":["Alto contenido de proteínas","Aspecto claro, seroso","Recuento bajo de leucocitos","Baja densidad"],"ok":[0],"w":["Proteína alta é a marca do exsudato.","Claro e seroso é transudato.","Poucas células é transudato.","Densidade baixa é transudato."],"nt":"Mesma questão da P2 Turma C (Q16)."},{"p":"p2f1","n":12,"t":"mc","tema":"inf","q":"Una niña de 4 años ha presentado numerosas infecciones por Staphylococcus aureus desde la lactancia. Las pruebas genéticas muestran un defecto causante de la ausencia de producción de β2-integrina. ¿Cuál de las siguientes alteraciones es más probable que ocurra por deficiencia de β2-integrina?","o":["Menor producción de radicales libres (ERO)","Adhesión neutrofílica inadecuada al endotelio","Reducción de la fagocitosis de bacterias opsonizadas","Fracaso del proceso en el cual los leucocitos se colocan sobre el endotelio de forma transitoria"],"ok":[1],"w":["Radicais dependem da NADPH oxidase.","β2-integrinas fazem a adesão firme: deficiência de adesão leucocitária tipo 1.","Efeito secundário (Mac-1 é receptor de iC3b); não é o principal.","Isso é rolamento, feito pelas selectinas."],"nt":"Mesma questão da P2 Turma C (Q19)."},{"p":"p2f1","n":13,"t":"mc","tema":"nec","q":"Mujer de 29 años con una comunicación interventricular lleva 3 semanas con fiebre persistente de 38,6 °C y cefalea. Una TAC craneal muestra una lesión en anillo de 3 cm, de contenido licuado, que capta contraste en el lóbulo parietal derecho del encéfalo. ¿Cuál de las siguientes acciones de las células inflamatorias es más probable que haya producido este hallazgo en la TAC?","o":["Elaboración de óxido nítrico por los macrófagos","Formación de inmunoglobulinas por linfocitos B","Liberación de enzimas lisosómicas por los neutrófilos","Producción de interferón γ por linfocitos T"],"ok":[2],"w":["O NO dos macrófagos mata micróbios e dilata vasos, mas não liquefaz tecido.","Imunoglobulinas opsonizam; não causam necrose.","Abscesso cerebral (endocardite com CIV, êmbolo séptico): as enzimas dos neutrófilos digerem o tecido e formam necrose liquefativa, a cavidade com conteúdo líquido.","IFN-γ ativa macrófagos: granuloma, inflamação crônica."],"nt":"Copiada do PEF (Q27)."},{"p":"p2f1","n":14,"t":"mc","tema":"inf","q":"Paciente femenina de 53 años sufre dolor abdominal de 2 semanas de evolución. No tiene fiebre; la zona superior del abdomen es ligeramente dolorosa, y se conservan los ruidos intestinales. Se realiza una biopsia y se observa una lesión duodenal caracterizada por pérdida local de la superficie mucosa que contiene restos necróticos inflamados. ¿Cuál de los siguientes procesos patológicos es más probable que esté presente?","o":["Úlceras","Absceso","Inflamación crónica","Exudado purulento"],"ok":[0],"w":["Perda local da superfície mucosa com restos necróticos inflamados é a definição de úlcera.","Abscesso é coleção de pus dentro do tecido.","O aluno marcou esta, e errou. A base de uma úlcera antiga tem inflamação crônica, mas a lesão descrita se chama úlcera.","Exsudato purulento é líquido, não perda de superfície."],"nt":"Copiada do PEF (Q25)."},{"p":"p2f2","n":1,"t":"cita","tema":"c7","q":"2 tipos de calcificación patológica:","a":"Distrófica y metastásica.","e":"Distrófica: tecido morto ou lesado, cálcio sérico normal. Metastásica: tecido normal, hipercalcemia."},{"p":"p2f2","n":2,"t":"cita","tema":"inf","q":"2 pasos del reclutamiento de leucocitos ocurridos en la luz vascular:","a":"Marginación y rodamiento (también adhesión).","e":"Na luz: marginação, rolamento e adesão. No tecido: transmigração e quimiotaxia (o Examen Final pergunta essa outra metade)."},{"p":"p2f2","n":3,"t":"cita","tema":"c7","q":"Mujer sana de 73 años cae por las escaleras y se lesiona la cadera derecha. No hay fractura, pero la radiografía revela calcificación de las pequeñas arterias musculares laterales al útero.","a":"Esclerosis medial calcificada.","e":"Idosa saudável, sem hipercalcemia, cálcio na média de artérias musculares: Mönckeberg.","nt":"O aluno escreveu \"calcificación metastásica\" e errou. Seção com quadro de opções: Hemosiderina · Trasudado · Calcificación metaplásica · Aterosclerosis ulcerosa · Bilirrubina · Esclerosis medial calcificada · Exudado purulento · Lipofuscina · Cuerpos de psamoma."},{"p":"p2f2","n":4,"t":"cita","tema":"pig","q":"Hombre de 35 años es golpeado en la pierna por un estante que cayó. La piel no está rota; 16 días después presenta una lesión de color amarillo-marrón producida por acumulación de una sustancia:","a":"Hemosiderina.","e":"O hematoma muda de cor: vermelho-azulado (Hb), verde-azulado (biliverdina), amarelo (bilirrubina) e por fim marrom-dourado (hemosiderina). Depois de duas semanas o que sobra é hemosiderina. Bilirrubina está no quadro como pegadinha."},{"p":"p2f2","n":5,"t":"cita","tema":"inf","q":"Hombre de 25 años lleva todo el día trabajando en su jardín. En el examen físico se observa una ampolla por fricción en la piel de las manos.","a":"Trasudado.","e":"No Robbins a resposta é \"inflamação serosa\". Como o quadro não tem \"serosa\", o termo que sobra para líquido pobre em proteína e células é trasudado. Exsudato purulento exigiria infecção.","nt":"Gabarito com ressalva: depende do quadro de opções."},{"p":"p2f2","n":6,"t":"comp","tema":"pig","q":"Las llamadas \"células de la insuficiencia cardíaca\" corresponden a acúmulos de pigmento de ________ dentro de ________.","a":"Hemosiderina; macrófagos alveolares.","e":"Congestão pulmonar crônica: hemácias no alvéolo, Hb degradada pelos macrófagos, ferro guardado como hemosiderina."},{"p":"p2f2","n":7,"t":"comp","tema":"pig","q":"Para confirmar el depósito de pigmento hemosiderínico en un paciente con anemia hemolítica se utiliza la tinción ________.","a":"Azul de Prusia (Perls).","e":"O ferro férrico reage com o ferrocianeto e fica azul. A bilirrubina não cora com Perls."},{"p":"p2f2","n":8,"t":"mc","tema":"c7","q":"¿Cuál de los siguientes enunciados corresponde a la calcificación distrófica?","o":["Es altamente sugestiva de una enfermedad renal crónica","Se observa en pacientes con hiperparatiroidismo primario","Puede observarse en placas ateromatosas complicadas","Es frecuente en la intoxicación por vitamina D"],"ok":[2],"w":["Renal crônica leva a hiperparatireoidismo secundário: metastásica.","Hiperparatireoidismo primário dá hipercalcemia: metastásica.","Ateroma avançado é tecido lesado com cálcio normal: distrófica (a aorta fica como casca de ovo).","Intoxicação por vitamina D dá hipercalcemia: metastásica."]},{"p":"par1","n":1,"t":"cita","tema":"apo","q":"Dos enzimas involucradas en el proceso de muerte por apoptosis.","a":"Caspasas y endonucleasas.","e":"Na correção o citocromo c foi anulado: não é enzima. Ele é uma proteína da cadeia respiratória que, no citosol, forma o apoptossomo com Apaf-1."},{"p":"par1","n":2,"t":"cita","tema":"nec","q":"Patrones de necrosis que presentan digestión enzimática.","a":"Necrosis licuefactiva y necrosis grasa.","e":"Digestão enzimática: liquefativa, gordurosa (lipases pancreáticas) e a gangrena úmida. Desnaturação de proteínas: coagulativa e gangrena seca. A caseosa é mistura e não é a resposta esperada."},{"p":"par1","n":3,"t":"cita","tema":"acu","q":"Dos componentes principales de las placas arterioscleróticas.","a":"Células (macrófagos/células espumosas, células musculares lisas, linfocitos T), matriz extracelular (colágeno, cápsula fibrosa) y lípidos (colesterol y ésteres de colesterol).","e":"O Robbins resume em três componentes: células, matriz extracelular e lipídios. Quaisquer dois valem."},{"p":"par1","n":4,"t":"comp","tema":"nec","q":"Picnosis es un cambio nuclear caracterizado por ________ nuclear y aumento de basofilia (la cromatina se condensa en una masa basófila sólida).","a":"Retracción (encogimiento).","e":"Picnose: núcleo pequeno, denso e hipercromático. Cariorrexe: fragmenta. Cariólise: perde a basofilia pela ação das DNases."},{"p":"par1","n":6,"t":"comp","tema":"acu","q":"La tinción ________ da una coloración azul negra a depósitos intracelulares excesivos de triglicéridos.","a":"Sudán negro B.","e":"Lipídios exigem corte por congelação, porque o álcool do processamento os dissolve. Sudão IV e Oil Red O coram de vermelho-alaranjado; Sudão negro B, de azul-negro. No H&E ficam só vacúolos vazios."},{"p":"par1","n":9,"t":"cita","tema":"apo","q":"La muerte causada por el aumento de la permeabilidad de la membrana mitocondrial externa, que permite la activación de sustancias citosólicas…","a":"Caspasas iniciadoras.","e":"Via intrínseca: BAX e BAK abrem a membrana externa, sai o citocromo c, que com Apaf-1 forma o apoptossomo e ativa a caspase 9, a iniciadora.","nt":"Seção com quadro de opções: Falla de bomba Na⁺/K⁺ · Lipasas pancreáticas activas · Síntesis de proteínas disminuidas · Necroptosis · Presencia de espacios quísticos · Colesterol LDL bajo · Gangrena seca · Aumento de la mitosis celular · Caspasas iniciadoras. Na P1 Turma C a mesma ideia tinha como resposta \"presencia de citocromo c\"."},{"p":"par1","n":10,"t":"cita","tema":"nec","q":"Mujer de 75 años sufrió pérdida de conocimiento. No puede hablar ni mover el brazo derecho a causa de una oclusión de la arteria cerebral media izquierda.","a":"Presencia de espacios quísticos.","e":"Infarto cerebral é necrose liquefativa (tecido rico em lipídios e pobre em estroma). Com o tempo vira uma cavidade cística."},{"p":"par1","n":12,"t":"mc","tema":"nec","q":"Al microscopio óptico, en un patrón de lesión celular irreversible, se podrá observar de forma característica:","o":["Vacuolas lipídicas transparentes en el citoplasma de las células","Presencia de masas de fosfolípidos llamadas figuras de mielina","Formación de vesículas en las membranas plasmáticas","Aumento de la acidofilia por medio de ARN citoplasmático"],"ok":[1],"w":["Vacúolos lipídicos (alteração gordurosa) são lesão reversível.","Frase do slide: na necrose as células podem ser substituídas por grandes massas de fosfolipídios, as figuras de mielina.","Bolhas na membrana são lesão reversível.","A eosinofilia aumenta pela PERDA do RNA (que fixa a hematoxilina) e pelas proteínas desnaturadas. \"Por meio de RNA\" inverte o mecanismo."]},{"p":"par1","n":14,"t":"mc","tema":"apo","q":"¿Qué trastorno clínico se asocia con una apoptosis fisiológica?","o":["Infección en el pie derecho en un paciente diabético","Paciente con demencia por enfermedad de Parkinson","Verrugas cutáneas en pacientes con infección por papilomavirus","Eliminación de las membranas interdigitales para la formación de los dedos"],"ok":[3],"w":["Pé diabético infectado é gangrena (necrose).","Neurodegeneração é apoptose PATOLÓGICA (proteínas mal dobradas).","O HPV inibe a apoptose (a E6 degrada a p53); a verruga é proliferação.","Embriogênese é o exemplo clássico de apoptose fisiológica."]},{"p":"par1","n":15,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes corresponde a una complicación de las placas ateromatosas?","o":["Taponamiento","Rotura del músculo papilar","Hemorragia pericárdica","Formación de aneurismas"],"ok":[3],"w":["Tamponamento é complicação do INFARTO (ruptura da parede livre), não da placa.","Ruptura de músculo papilar também é complicação do infarto.","Hemopericárdio vem da ruptura cardíaca pós-infarto.","A placa atrofia a média e enfraquece a parede: aneurisma (aorta abdominal). Outras: ruptura, hemorragia intraplaca, trombose, ateroembolia e calcificação."]},{"p":"par1","n":16,"t":"mc","tema":"acu","q":"¿Cuál de las siguientes coloraciones sería la preferible para evidenciar adecuadamente la presencia de acumulaciones intracelulares en la glucogenosis tipo IV?","o":["Hematoxilina y eosina","Tricrómica de Mallory","Ácido peryódico de Schiff","Aceite rojo O"],"ok":[2],"w":["No H&E o glicogênio aparece só como vacúolo claro.","Tricrômico cora colágeno.","PAS cora glicogênio de magenta (confirma com diastase). Carmim de Best também serve.","Oil Red O é para lipídios."]},{"p":"par1","n":19,"t":"mc","tema":"nec","q":"Hombre de 55 años que tiene DM mal controlada hace 15 años presentó una extensa coloración negra de la piel y tejidos blandos del pie derecho con áreas de exudado amarillento. Se cultiva Staphylococcus aureus y se realiza la amputación. ¿Cuál de las siguientes anomalías patológicas tiene más probabilidad de mostrar la muestra recibida en el laboratorio?","o":["Apoptosis patológica","Infarto rojo","Gangrena húmeda","Necrosis caseosa"],"ok":[2],"w":["Apoptose não deixa o membro preto nem gera exsudato.","Infarto vermelho é de órgão com dupla circulação (pulmão, intestino).","Isquemia (coagulativa) com infecção bacteriana sobreposta (liquefativa) e exsudato: gangrena úmida.","Caseosa é da tuberculose."]},{"p":"p1c","n":1,"t":"cita","tema":"acu","q":"Dos rasgos macroscópicos presentes en el hígado con esteatosis:","a":"Hígado aumentado de tamaño y peso, amarillo, blando y grasoso, con cápsula tensa y brillante y bordes redondeados.","e":"Use os termos do slide. A resposta anotada pelo aluno (\"bordes regulares, cápsula densa\") não confere."},{"p":"p1c","n":2,"t":"cita","tema":"nec","q":"Dos patrones de necrosis que presentan primariamente desnaturalización de proteínas:","a":"Necrosis coagulativa y gangrena seca.","e":"Desnaturação conserva o contorno da célula (coagulativa). A gangrena seca é coagulativa num membro."},{"p":"p1c","n":3,"t":"cita","tema":"acu","q":"Dos cambios patológicos que pueden sufrir las placas ateroscleróticas:","a":"Rotura, ulceración o erosión; hemorragia intraplaca; trombosis; formación de aneurisma; calcificación.","e":"Quaisquer dois da lista de complicações da placa."},{"p":"p1c","n":4,"t":"comp","tema":"nec","q":"La ________ es un cambio nuclear caracterizado por pérdida de basofilia de la cromatina debido a la disolución nuclear por degradación enzimática.","a":"Cariólisis.","e":"Cariólise: a DNase dissolve a cromatina e o núcleo some. O aluno transcreveu \"cariosis\"."},{"p":"p1c","n":6,"t":"comp","tema":"acu","q":"La tinción con carmín de Best o PAS da lugar a una coloración rosa violácea al depósito de ________.","a":"Glucógeno.","e":"PAS e carmim de Best para glicogênio; confirma com digestão por diastase."},{"p":"p1c","n":8,"t":"cita","tema":"apo","q":"Cuadro comparativo: características entre apoptosis y necrosis (membrana plasmática, inflamación, tamaño celular, contexto).","a":"Necrosis: membrana rota, célula aumentada (tumefacción), con inflamación, siempre patológica. Apoptosis: membrana conservada, célula encogida, sin inflamación, forma cuerpos apoptóticos, fisiológica o patológica.","e":"Quadro clássico do Robbins: veja o comparativo da Clase 5."},{"p":"p1c","n":9,"t":"cita","tema":"apo","q":"La muerte causada por aumento de la permeabilidad de la membrana mitocondrial externa causa a veces la salida de unas proteínas al citosol.","a":"Presencia de citocromo c.","e":"Via mitocondrial: o citocromo c sai para o citosol e forma o apoptossomo.","nt":"Seção com quadro: Falla de bomba de sodio-potasio · Síntesis de proteínas aumentada · Piroptosis · Presencia de citocromo c · Colesterol LDL bajo · Gangrena seca · Necrosis caseosa · División celular aumentada."},{"p":"p1c","n":10,"t":"cita","tema":"nec","q":"Paciente de 70 años presenta un cuadro respiratorio de meses de evolución, y a nivel del vértice del pulmón derecho se observan imágenes granulomatosas.","a":"Necrosis caseosa.","e":"Ápice pulmonar, evolução de meses e granuloma: tuberculose."},{"p":"p1c","n":12,"t":"mc","tema":"nec","q":"Al microscopio óptico, en un patrón de lesión celular reversible, se podrá observar:","o":["Vacuolas lipídicas transparentes en el citoplasma de la célula","Presencia de masas de fosfolípidos y figuras de mielina","Calcificación […] que genera carbonatos de calcio","Aumento de eosinofilia por pérdida de ARN en el citoplasma"],"ok":[0],"w":["Ao microscópio óptico a lesão reversível mostra tumefação celular e alteração gordurosa (vacúolos lipídicos).","Grandes massas de fosfolipídios substituindo a célula são da necrose.","Calcificação é de tecido morto (distrófica). Alternativa truncada na transcrição.","Eosinofilia por perda de RNA é sinal de necrose."]},{"p":"p1c","n":14,"t":"mc","tema":"apo","q":"¿Qué trastorno clínico se asocia con apoptosis patológica?","o":["Infección en el pie derecho en un paciente diabético","Paciente con demencia por enfermedad de Parkinson","Verrugas cutáneas en un paciente con infección por papilomavirus","Disminución del flujo sanguíneo miocárdico por aterosclerosis coronaria"],"ok":[1],"w":["Pé diabético infectado é gangrena.","Proteínas mal dobradas causam estresse do retículo e apoptose dos neurônios: apoptose patológica.","O HPV bloqueia a apoptose.","Isquemia miocárdica dá necrose coagulativa."]},{"p":"p1c","n":15,"t":"mc","tema":"acu","q":"¿Cuál de los siguientes es un factor de riesgo adquirido para el desarrollo de ateromas?","o":["Sexo masculino","Consumo moderado de alcohol","Síndrome metabólico","Aumento del colesterol LDL"],"ok":[3],"w":["Sexo é fator não modificável.","Consumo moderado de álcool até sobe o HDL; não é fator de risco.","Também é adquirido. Se o slide dela listar síndrome metabólica entre os fatores modificáveis, a questão tem duas certas.","LDL alto é o principal fator modificável, capaz sozinho de iniciar a aterosclerose."],"nt":"Questão ambígua: c e d são adquiridos. Na prova, a resposta esperada é a d."},{"p":"p1c","n":16,"t":"mc","tema":"pig","q":"Con respecto a la atrofia parda, ¿cuál de los siguientes es correcto?","o":["Ocurre en situaciones de pérdida de estimulación endocrina","Algunos de los residuos celulares del proceso constituyen los gránulos de hemosiderina","Las células atrofiadas intentan aumentar la demanda nutricional","Va acompañada de un incremento de vacuolas autofágicas"],"ok":[3],"w":["Perda de estímulo endócrino causa atrofia, mas a atrofia \"parda\" é a do idoso e da caquexia.","Os restos formam LIPOFUSCINA, não hemosiderina.","A atrofia REDUZ a demanda; é adaptação.","Na atrofia a autofagia aumenta; o que não se digere fica como corpos residuais de lipofuscina, que dão a cor parda."],"nt":"O tema é adaptação (P1), mas o pigmento lipofuscina é da P2."},{"p":"p1c","n":17,"t":"mc","tema":"apo","q":"En el estudio de la infección por VIH se observa a los linfocitos T citotóxicos provocando la muerte de las células infectadas por el virus. ¿Cuál de las siguientes sustancias inicia la muerte celular programada?","o":["BCL2","Endonucleasas","Caspasas","Gen TP53"],"ok":[2],"w":["BCL2 é antiapoptótica.","Endonucleases são executoras tardias que fragmentam o DNA, ativadas pelas caspases.","O linfócito T citotóxico usa perforina e granzima B (que ativa caspases diretamente) e FasL-Fas (caspase 8).","p53 inicia apoptose por dano no DNA, não pela via do linfócito citotóxico."]},{"p":"p1c","n":18,"t":"mc","tema":"nec","q":"Paciente de sexo femenino de 30 años de edad con diagnóstico de lupus eritematoso sistémico, enfermedad donde se producen reacciones inflamatorias de etiología inmunológica.","o":["Necrosis fibrinoide","Gangrena húmeda","Infarto blanco","Granuloma necrosado"],"ok":[0],"w":["Imunocomplexos e fibrina na parede dos vasos: aspecto rosa e amorfo. Típica de vasculites imunes (LES, PAN).","Gangrena úmida é isquemia com infecção.","Infarto branco é oclusão arterial em órgão de circulação terminal.","Granuloma necrosante é da tuberculose e dos fungos."]},{"p":"par1r","n":1,"t":"cita","tema":"acu","q":"Vesícula biliar con patrón en fresa, muestra microscópicamente numerosos [macrófagos] espumosos en la lámina propia.","a":"Aumento de colesterol (colesterolosis).","e":"Macrófagos cheios de colesterol na lâmina própria dão os pontinhos amarelos de \"morango\".","nt":"Seção com quadro: Sexo masculino · Necrosis fibrinoide · Necroptosis · Aumento de colesterol · Digestión enzimática · Colestasis · Displasia escamosa · Aumento de la mitosis celular · Metaplasia intestinal."},{"p":"par1r","n":3,"t":"cita","tema":"nec","q":"Mujer de 30 años fallece por lupus eritematoso sistémico, enfermedad donde hay reacciones inflamatorias de etiología inmunológica que han afectado las paredes de los vasos sanguíneos.","a":"Necrosis fibrinoide.","e":"Imunocomplexos e fibrina na parede vascular."},{"p":"par1r","n":4,"t":"cita","tema":"acu","q":"Dos factores de riesgo no modificables para el desarrollo de placas ateromatosas.","a":"Edad avanzada y sexo masculino (también antecedentes familiares o genética).","e":"Modificáveis: hiperlipidemia, hipertensão, tabagismo, diabetes."},{"p":"par1r","n":5,"t":"cita","tema":"acu","q":"Dos tinciones específicas para evidenciar las acumulaciones intracelulares de glucógeno.","a":"PAS y carmín de Best.","e":"O PAS tem de ser confirmado com diastase, porque também cora mucinas."},{"p":"par1r","n":6,"t":"cita","tema":"nec","q":"Dos cambios nucleares que se encuentran en una célula necrótica (no se aceptan descripciones).","a":"Picnosis y cariorrexis (o cariólisis).","e":"Ela pede o nome, não a descrição."},{"p":"par1r","n":7,"t":"comp","tema":"nec","q":"Los infartos que macroscópicamente presentan una forma de cuña, que se clasifican según su color, corresponden histológicamente a una necrosis ________.","a":"Coagulativa.","e":"Infarto em cunha (vértice no vaso ocluído) de órgão sólido: necrose coagulativa. Exceção: cérebro, liquefativa."},{"p":"par1r","n":8,"t":"comp","tema":"apo","q":"Las células tienen mecanismos por los cuales reparan el daño en el ADN, aunque cuando la afectación es demasiado grave la célula inicia un proceso de muerte que corresponde a ________.","a":"Apoptosis.","e":"Dano no DNA ativa p53, que induz PUMA e NOXA, que ativam BAX e BAK: via intrínseca."},{"p":"par1r","n":9,"t":"comp","tema":"pig","q":"Hombre de 70 años presenta atrofia parda en el corazón; en la autopsia el corazón pesa solo 250 g. Microscópicamente se ve que las fibras miocárdicas muestran cantidades excesivas de pigmento ________.","a":"Lipofuscina.","e":"Pigmento do desgaste, perinuclear, marrom-amarelado, de lipídios peroxidados."},{"p":"par1r","n":11,"t":"mc","tema":"nec","q":"Al microscopio electrónico, en un patrón de lesión celular reversible, se podrá observar:","o":["Rotura de la membrana plasmática","Dilatación masiva de la mitocondria","Presencia de figuras de mielina","Aumento de acidofilia"],"ok":[2],"w":["Ruptura de membrana é lesão irreversível.","Tumefação MASSIVA com grandes densidades amorfas é irreversível; na reversível a tumefação é leve.","Na microscopia eletrônica da lesão reversível: bolhas, perda de microvilos, tumefação mitocondrial leve, dilatação do retículo e figuras de mielina.","Acidofilia é achado de microscopia óptica e de necrose."]},{"p":"par1r","n":14,"t":"mc","tema":"nec","q":"¿Cuál de los siguientes trastornos clínicos se asocia a necrosis licuefactiva?","o":["Infección aguda por el virus de la hepatitis B","Lesión vascular en el pie derecho de un paciente diabético","Infarto del miocardio en paciente con aterosclerosis","Infarto cerebral por trombosis"],"ok":[3],"w":["Hepatite viral mata hepatócitos por apoptose (corpos de Councilman).","Isquemia do pé diabético dá gangrena (coagulativa; úmida se infectar).","Infarto do miocárdio é coagulativo.","Infarto cerebral é liquefativo."]},{"p":"par1r","n":15,"t":"mc","tema":"nec","q":"¿Cuál de los siguientes cambios morfológicos es más probable que apunte a una necrosis tubular aguda?","o":["Aumento de basofilia","Pérdida de microvellosidades","Tumefacción de las mitocondrias","Núcleos que sufren fragmentación"],"ok":[3],"w":["Na necrose aumenta a EOSINOFILIA, não a basofilia.","Perda de microvilos é lesão reversível.","Tumefação mitocondrial (leve) é lesão reversível.","Cariorrexe é sinal de célula morta."]},{"p":"par1r","n":17,"t":"mc","tema":"acu","q":"Una mujer de 69 años ha sufrido [episodios isquémicos] transitorios en los últimos 3 meses. En la [carótida] derecha se reseca una placa ateromatosa de aspecto firme, color amarillo oscuro a simple vista. Microscópicamente, ¿qué sustancias podemos encontrar en abundancia?","o":["Triglicéridos y lipoproteínas","Colesterol y ésteres de colesterol","Fosfolípidos y ácidos grasos libres","Triglicéridos y […]"],"ok":[1],"w":["Triglicérides não são o lipídio da placa.","O núcleo lipídico é colesterol e ésteres de colesterol, que cristalizam nas fendas de colesterol.","Fosfolipídios não predominam.","Triglicérides de novo; errada."]},{"p":"par1r","n":19,"t":"mc","tema":"acu","q":"Hombre de 73 años consulta por dolor abdominal; en el examen el hígado mide dos veces el tamaño normal, amarillo, de superficie lisa. Microscópicamente se muestran numerosas vacuolas transparentes en el citoplasma de los hepatocitos. ¿Cuál de las siguientes opciones podría ser la posible causa de las alteraciones del paciente?","o":["Infección por el virus de hepatitis","Alimentación rica en fibras","Consumo de alcohol","Anemia hemolítica"],"ok":[2],"w":["Hepatite viral dá apoptose e inflamação, não esteatose macro.","Fibra não causa esteatose.","Álcool é a causa mais comum de esteatose (com obesidade e diabetes).","Anemia hemolítica dá hemossiderose."]},{"p":"par1r","n":20,"t":"mc","tema":"nec","q":"Mujer de 78 años perdió el conocimiento de repente; no podía hablar ni mover el brazo derecho. A los dos meses una tomografía mostró una gran área quística en el lóbulo parietal izquierdo. ¿Cuál de los siguientes procesos patológicos es más probable que haya tenido lugar en el encéfalo?","o":["Necrosis gangrenosa con formación de cavitaciones","Infiltrados neutrofílicos con restos licuados","Lesión granulomatosa que presenta células multinucleadas","Granuloma que presenta centralmente depósitos de inmunocomplejos"],"ok":[1],"w":["Gangrena é termo de membro, não de cérebro.","Infarto cerebral é necrose liquefativa: neutrófilos e restos liquefeitos que, removidos, deixam a cavidade cística.","Granuloma é tuberculose, fungos e corpo estranho.","Não existe esse padrão."]},{"p":"final24","n":4,"t":"cita","tema":"inf","q":"Mediadores químicos denominados \"anafilotoxinas\":","a":"C3a y C5a.","e":"Fazem os mastócitos liberarem histamina (vasodilatação e permeabilidade). O C5a também é quimiotático. O C4a é anafilatoxina fraca."},{"p":"final24","n":5,"t":"comp","tema":"c7","q":"La calcificación ________ se caracteriza por depósitos de calcio en tejidos viables como consecuencia de hipercalcemia secundaria a un aumento de PTH.","a":"Metastásica.","e":"Tecido vivo e normal mais hipercalcemia (PTH alto, destruição óssea, vitamina D, insuficiência renal)."},{"p":"final24","n":10,"t":"cita","tema":"inf","q":"Las bacterias son fagocitadas por neutrófilos o bien sufren lisis. ¿Qué componente del plasma sanguíneo es más probable que facilite estos efectos?","a":"Complemento.","e":"C3b opsoniza e C5b-9 faz lise. Copiada do PEF (Q19)."},{"p":"final24","n":13,"t":"cita","tema":"c7","q":"Hombre de 67 años falleció debido a una insuficiencia cardíaca congestiva. En la autopsia el corazón pesa 580 g (normal 330 g) y muestra hipertrofia del ventrículo izquierdo y área valvular aórtica disminuida. El hallazgo bioquímico sérico solicitado antes fue normal. ¿Qué tipo de calcificación patológica explica mejor la afectación de la válvula aórtica?","a":"Calcificación distrófica.","e":"Estenose aórtica calcificada do idoso: desgaste valvar com cálcio sérico normal. A pista é \"bioquímica normal\"."},{"p":"final24","n":16,"t":"mc","tema":"c7","q":"Los cuerpos de psamoma corresponden a un tipo de calcificación:","o":["Displásica","Distrófica","Metastásica","Atrófica"],"ok":[1],"w":["\"Displásica\" não é tipo de calcificação.","Psamoma é calcificação distrófica em lâminas concêntricas sobre papilas de tumor.","Metastásica exige hipercalcemia.","\"Atrófica\" não é tipo de calcificação."]},{"p":"final24","n":20,"t":"mc","tema":"inf","q":"Teniendo en cuenta los siguientes mediadores químicos y sus efectos correspondientes, marca la alternativa correcta:","o":["Leucotrieno B4, aumento de permeabilidad vascular","C5b-9, proceso de lisis celular","Prostaciclina, vasoconstrictor","IL-6, quimiotáctico"],"ok":[1],"w":["LTB4 é quimiotático. Quem aumenta permeabilidade são LTC4, D4 e E4.","O complexo de ataque à membrana abre poros e lisa a célula.","Prostaciclina é vasodilatadora. O vasoconstritor é o tromboxano A2.","IL-6 dá febre e fase aguda. Quimiotática é a IL-8."]},{"p":"final24","n":23,"t":"mc","tema":"inf","q":"Un grupo de pacientes recibe un inhibidor de la ciclooxigenasa 2 (COX-2). Los hombres adultos tenían artritis de pequeñas articulaciones. Refieren que el fármaco ha presentado ciertos efectos. ¿Cuál de los siguientes hallazgos es más probable que refiera el grupo que recibió el fármaco?","o":["Numerosos episodios febriles","Reducción del dolor articular","Mayor tumefacción de los tobillos"],"ok":[1],"w":["Inibir a COX-2 reduz a febre.","Menos PGE2, menos sensibilização dos nociceptores: menos dor.","Edema é efeito adverso possível, mas não o achado esperado."],"nt":"Mesma questão da P2 Turma C (Q17), copiada do PEF (Q15)."},{"p":"final24","n":29,"t":"cita","tema":"inf","q":"Fases del trayecto leucocitario que acontecen en la luz vascular:","a":"Marginación, rodamiento, adhesión.","e":"Transmigração e quimiotaxia já acontecem fora da luz.","nt":"Só na transcrição digitada, sem foto. Numeração do aluno."},{"p":"final24","n":30,"t":"cita","tema":"inf","q":"¿Cuáles son los mediadores químicos derivados de células que causan vasodilatación?","a":"Histamina y prostaglandinas (también óxido nítrico).","e":"A bradicinina dilata, mas é plasmática: o próprio aluno anotou \"bradicinina no es derivada de célula\".","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":32,"t":"cita","tema":"inf","q":"¿Cuál es el mediador en reacciones alérgicas?","a":"Histamina.","e":"Hipersensibilidade tipo I: IgE no mastócito, degranulação, histamina.","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":33,"t":"cita","tema":"inf","q":"Proceso de redistribución leucocitaria: los leucocitos adoptan una posición periférica a lo largo de la superficie endotelial.","a":"Marginación.","e":"É a frase que na recuperatória de 2023 aparece como falsa atribuída à \"migración\".","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":34,"t":"cita","tema":"inf","q":"Dos procesos de reclutamiento de leucocitos que acontecen en el tejido:","a":"Transmigración (diapédesis) y quimiotaxis.","e":"Complementa a pergunta da luz vascular (marginação, rolamento, adesão).","nt":"Só na transcrição digitada, sem foto."},{"p":"final24","n":36,"t":"cita","tema":"nec","q":"La necrosis observada en el trastorno de una infección por bacteria piógena es un ejemplo de:","a":"Necrosis licuefactiva.","e":"Bactérias piogênicas atraem neutrófilos, cujas enzimas digerem o tecido: pus.","nt":"Só na transcrição digitada, sem foto."},{"p":"robbins","n":1,"t":"mc","tema":"inf","q":"Un hombre de 22 años presenta un dolor abdominal intenso en el cuadrante inferior derecho durante el último día. […] el apéndice está hinchado, eritematoso y parcialmente cubierto por un exudado amarillento. Se extirpa y un corte microscópico muestra infiltración con numerosos neutrófilos. El dolor experimentado por este paciente es [mediado principalmente por]:","o":["Complemento C3b e IgG","Interleucina-1 y factor de necrosis tumoral","Histamina y serotonina","Prostaglandina y bradicinina","Leucotrienos y HPETE"],"ok":[3],"w":["Opsoninas.","Febre e fase aguda.","Vasodilatação e permeabilidade imediatas, não a dor sustentada.","A PGE2 sensibiliza as terminações à bradicinina: dor. A aspirina alivia por isso.","Broncoespasmo, permeabilidade, quimiotaxia."],"nt":"Ela copiou na P2 Turma D (Q19)."},{"p":"robbins","n":4,"t":"mc","tema":"inf","q":"Una mujer de 58 años ha tenido tos con fiebre durante 3 días. Una radiografía de tórax revela infiltrados en el lóbulo inferior derecho. En un cultivo de esputo crece Streptococcus pneumoniae. La eliminación de estos organismos del parénquima pulmonar se lograría de manera más efectiva mediante la generación de ¿cuál de las siguientes sustancias por el principal tipo de célula inflamatoria que responde a esta infección?","o":["Factor activador de plaquetas","Prostaglandina E2","Calicreína","Leucotrieno B4","Peróxido de hidrógeno"],"ok":[4],"w":["PAF: agregação plaquetária, permeabilidade, broncoconstrição.","Vasodilatação, dor, febre.","Gera bradicinina.","Quimiotaxia.","H2O2 convertido pela mieloperoxidase em HOCl: o bactericida mais potente do neutrófilo."],"nt":"Ela copiou na P2 Turma C (Q18)."},{"p":"robbins","n":5,"t":"mc","tema":"inf","q":"Se realiza un estudio clínico de pacientes con infecciones faríngeas. El curso clínico más típico es de 3 días en promedio desde el momento de la aparición hasta que el paciente ve al médico. La mayoría de estos pacientes experimentan fiebre y escalofríos. En el examen físico, los hallazgos más comunes incluyen hinchazón, eritema y exudado purulento faríngeo. ¿Cuál de los siguientes tipos de inflamación tenían más probablemente estos pacientes?","o":["Granulomatoso","Agudo","Gangrenoso","Resolviendo","Crónico"],"ok":[1],"w":["Granulomatosa é crônica, com macrófagos epitelioides.","Curso curto (dias) e exsudato purulento, típico de estreptococo: inflamação aguda.","Gangrena é necrose de membro ou víscera.","Ainda há exsudato ativo; não está em resolução.","Crônica é de semanas a meses, com mononucleares."]},{"p":"robbins","n":7,"t":"mc","tema":"inf","q":"Una mujer de 22 años tiene un parto prematuro con rotura prematura de membranas fetales a las 20 semanas de gestación. Antes de ese momento, el embarazo se había desarrollado con normalidad. Dos días después, se produce un parto sin vida. El examen […] El parto prematuro probablemente estuvo mediado por los efectos de la liberación de ¿cuál de las siguientes sustancias?","o":["Inmunoglobulina","Prostaglandina","Complemento","Fibrinógeno","Linfocinas"],"ok":[1],"w":["Anticorpos não contraem o útero.","A corioamnionite libera prostaglandinas, que contraem o músculo liso uterino e desencadeiam o parto.","Complemento: opsonização, quimiotaxia, lise.","Fibrinogênio: coagulação e exsudato fibrinoso.","Linfocinas são da resposta imune adaptativa."],"nt":"O OCR perdeu uma linha do enunciado (marcada com […])."},{"p":"robbins","n":10,"t":"mc","tema":"inf","q":"Un hombre de 20 años ha tenido dolor al orinar durante 4 días. Se sospecha uretritis y se realiza un cultivo de Neisseria gonorrhoeae. En un frotis del exudado de la uretra del pene se encuentran numerosos neutrófilos. Estos neutrófilos experimentan diapédesis para llegar a los organismos. ¿Cuál de los siguientes mediadores químicos es más probable que provoque la exudación de neutrófilos?","o":["Histamina","Prostaglandina","Factor de Hageman","Bradicinina","Complemento"],"ok":[4],"w":["Histamina aumenta a permeabilidade, mas não atrai neutrófilos.","PG: vasodilatação, dor, febre.","Hageman ativa coagulação e cininas.","Bradicinina: dor e permeabilidade.","O C5a é potente quimiotático para neutrófilos."]},{"p":"robbins","n":12,"t":"mc","tema":"nec","q":"Una mujer de 94 años ha presentado fiebre y tos durante los últimos 2 días. Se realiza un cultivo de Staphylococcus aureus en su esputo. Recibe un tratamiento antibiótico. Dos semanas después ya no tiene tos productiva, pero sigue teniendo fiebre. Una radiografía de tórax revela una densidad redondeada de 3 cm en el lóbulo inferior derecho cuyo contenido licuado forma un nivel hidroaéreo central. No hay infiltrados circundantes. ¿Cuál de las siguientes es la mejor descripción de este resultado de su neumonía?","o":["Cicatriz hipertrófica","Formación de abscesos","Regeneración","Carcinoma broncogénico","Inflamación crónica","Cavitación granulomatosa"],"ok":[1],"w":["Cicatriz não tem conteúdo líquido.","Cavidade com conteúdo liquefeito e nível hidroaéreo depois de S. aureus: necrose liquefativa, abscesso.","Regeneração devolve a arquitetura normal.","Nada sugere tumor.","Seria infiltrado mononuclear e fibrose, não cavidade líquida.","Cavidade granulomatosa é da TB (caseosa)."]},{"p":"robbins","n":13,"t":"mc","tema":"inf","q":"Una mujer de 36 años ha estado tomando ácido acetilsalicílico (aspirina) para la artritis durante los últimos 4 años. Su dolor articular se ha reducido temporalmente gracias a esta terapia. Sin embargo, ahora se ha identificado sangre oculta en sus heces. ¿Cuál de las siguientes sustancias es más probable que sea inhibida por la aspirina y cause esta complicación?","o":["Leucotrieno B4","Interleucina-1","Tromboxano","Bradicinina","Factor de Hageman"],"ok":[2],"w":["A aspirina não bloqueia a lipoxigenase.","IL-1 não depende da COX.","A aspirina acetila a COX das plaquetas de forma irreversível e corta o tromboxano A2: as plaquetas não tampam pequenas lesões e o paciente sangra.","Bradicinina vem das cininas.","Hageman é fator XII."]},{"p":"robbins","n":14,"t":"mc","tema":"inf","q":"Un hombre de 25 años se incrusta en el dedo una pequeña astilla de madera, que no retira y, en los tres días siguientes, la zona que la rodea se enrojece, se hincha y duele. Los neutrófilos migran al tejido lesionado. ¿Cuál de las siguientes sustancias se expresa en las células endoteliales y es la más importante para promover esta reacción inflamatoria?","o":["Interferón gamma","Factor de Hageman","Lisozima","E-selectina","Prostaciclina"],"ok":[3],"w":["IFN-γ ativa macrófagos.","Fator plasmático.","Enzima dos grânulos.","Selectinas endoteliais iniciam o rolamento. A P-selectina sai em minutos; a E-selectina é induzida por IL-1/TNF em horas.","Vasodilatador e antiagregante."]},{"p":"robbins","n":16,"t":"mc","tema":"inf","q":"Un hombre de 37 años ha tenido náuseas y vómitos durante 5 semanas. Ayer experimentó un episodio de hematemesis. En el examen físico no presenta hallazgos anormales. Se realiza una endoscopia del tracto gastrointestinal superior y se observa una lesión de 1,5 cm de diámetro en el antro gástrico con pérdida de la superficie epitelial. ¿Estos hallazgos son más típicos de cuál de los siguientes procesos patológicos?","o":["Absceso","Serositis","Granuloma","Gangrena","Úlcera"],"ok":[4],"w":["Pus dentro do tecido.","Inflamação de serosa.","Macrófagos epitelioides.","Necrose de membro.","Perda de superfície epitelial com inflamação."],"nt":"Ela copiou na P2 Turma C (Q20)."},{"p":"robbins","n":18,"t":"mc","tema":"inf","q":"Una mujer de 19 años que trabaja en un espacio cerrado pasa el día fuera trabajando en el jardín. No lleva sombrero ni protector solar. Esa noche, su pareja comenta que tiene la cara roja. ¿Cuál de los siguientes cambios dérmicos es más probable que explique su aspecto rojo?","o":["Agregación de neutrófilos","Hemorragia","Edema","Hemólisis","Vasodilatación"],"ok":[4],"w":["Neutrófilos não dão vermelhidão difusa.","Hemorragia não some quando a pele é comprimida.","Edema dá inchaço (tumor), não rubor.","Hemólise não tem relação.","Queimadura solar: PGs e histamina dilatam os vasos e dão rubor."]},{"p":"robbins","n":20,"t":"mc","tema":"nec","q":"Un hombre de 55 años tiene antecedentes de hipercolesterolemia con enfermedad de la arteria coronaria y sufrió un infarto de miocardio hace 2 años. Ahora presenta un dolor torácico subesternal opresivo. ¿Cuál de las siguientes pruebas de laboratorio es más útil para diagnosticar la causa de su dolor torácico?","o":["Aumento del recuento de glóbulos blancos","Tasa de sedimentación elevada","Disminución del complemento sérico","Aumento de la troponina sérica","Recuento de plaquetas disminuido","Aumento del colesterol sérico"],"ok":[3],"w":["Inespecífico.","Inespecífico.","Não tem relação.","A membrana da célula necrótica deixa sair troponina, específica do músculo cardíaco: prova de necrose miocárdica.","Não tem relação.","É fator de risco, não diagnóstico de infarto."]},{"p":"robbins","n":21,"t":"mc","tema":"inf","q":"Una niña de 15 años ha tenido episodios de estornudos con ojos llorosos y secreción nasal durante las últimas 2 semanas. En el examen físico presenta superficies de la mucosa nasal enrojecidas e hinchadas. Ha tenido episodios similares cada primavera y verano, cuando la cantidad de polen en el aire es alta. ¿Es más probable que sus síntomas estén mediados por la liberación de cuál de los siguientes mediadores químicos?","o":["Complemento C3b","Factor activador de plaquetas (PAF)","Factor de necrosis tumoral (TNF)","Histamina","Inmunoglobulina G"],"ok":[3],"w":["Opsonina.","Participa, mas não é o principal.","Citocina sistêmica.","Mastócitos perivasculares da mucosa nasal liberam histamina: vasodilatação e exsudação. Por isso se usa anti-histamínico.","A alergia é por IgE, e anticorpo não é mediador de vasodilatação."]},{"p":"robbins","n":22,"t":"mc","tema":"inf","q":"Un hombre de 45 años ha trabajado duro todo el día cargando montones de ladrillos para construir un muro. Toma un medicamento antiinflamatorio no esteroideo (ibuprofeno). ¿Cuál de los siguientes procesos es más probable que disminuya este medicamento en sus brazos?","o":["Trombosis","Dolor","Necrosis","Fibrinólisis","Formación de cicatrices"],"ok":[1],"w":["O efeito antiplaquetário do ibuprofeno é pequeno e reversível; não é o objetivo.","AINE bloqueia a COX e reduz as prostaglandinas que causam dor.","Não há necrose.","AINE não mexe na fibrinólise.","Não há cicatriz."]},{"p":"robbins","n":23,"t":"mc","tema":"inf","q":"A los pocos minutos de ser picado por una abeja, un hombre de 37 años presenta un marcado estridor respiratorio con disnea y […]. ¿[Cuál de los siguientes mediadores explica mejor los síntomas] de este hombre?","o":["Bradicinina","Complemento C5a","Óxido nítrico","Factor de necrosis tumoral","Histamina"],"ok":[4],"w":["Bradicinina é do angioedema hereditário, não da anafilaxia por picada.","C5a é anafilatoxina, mas o mediador direto é a histamina.","NO dilata vasos, mas não é o mediador inicial.","Citocina, mais lenta.","Anafilaxia (tipo I): o antígeno se liga à IgE no mastócito, que libera histamina em minutos."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":25,"t":"mc","tema":"inf","q":"En un experimento, se añaden organismos del tipo Enterobacter cloacae a una solución que contiene leucocitos y plasma sanguíneo. […] destruyen más bacterias. ¿Cuál de las siguientes sustancias presentes en el plasma es más probable que produzca este efecto?","o":["Complemento C3b","Glutatión peroxidasa","Inmunoglobulina M","P-selectina","NADPH oxidasa"],"ok":[0],"w":["O C3b é opsonina: recobre a bactéria e o fagócito a engole mais fácil.","Antioxidante intracelular.","IgM ativa o complemento, mas os fagócitos não têm receptor para ela.","Molécula do endotélio, não do plasma.","Enzima dentro do fagócito, não do plasma."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":27,"t":"mc","tema":"inf","q":"Un hombre de 31 años tiene una herida punzante en el pulgar, que se infecta secundariamente con organismos del tipo […]. ¿[Cuál es la función de los vasos linfáticos] para producir una respuesta inmunitaria específica a estos organismos?","o":["Transportar linfocitos a sitios de tejido periférico","Eliminar el líquido del tejido extravascular","Transportar células presentadoras de antígenos","Servir como vía de diseminación de la infección","Proporcionar un punto de emigración para los neutrófilos"],"ok":[2],"w":["Linfócitos chegam ao tecido pelo sangue.","Drenam o edema, mas isso não gera resposta específica.","Células dendríticas e macrófagos levam o antígeno aos linfonodos, onde encontram os linfócitos específicos.","Pode acontecer (linfangite), mas não produz resposta específica.","Neutrófilos saem pelas vênulas pós-capilares."],"nt":"O OCR perdeu uma linha do enunciado."},{"p":"robbins","n":29,"t":"mc","tema":"inf","q":"Un hombre de 55 años con antecedentes de enfermedad pulmonar obstructiva crónica presenta insuficiencia cardíaca congestiva que empeora. Ha notado un aumento de la disnea y la ortopnea durante los últimos 2 meses. En el examen físico hay matidez a la percusión en las bases pulmonares. Una radiografía de tórax muestra derrames pleurales bilaterales. Se realiza una toracocentesis izquierda y se obtienen 500 ml de líquido. ¿Cuál de las siguientes características de este líquido indicaría con mayor probabilidad que se trata de un trasudado?","o":["Aspecto nublado","Alto contenido de proteínas","Recuento bajo de leucocitos","Presencia de fibrina","Gran tamaño del derrame"],"ok":[2],"w":["Turvo é exsudato.","Proteína alta é exsudato.","Transudato é ultrafiltrado de plasma: poucas células, pouca proteína, transparente.","Fibrina é exsudato.","Volume não distingue."],"nt":"É a mesma situação das P2, só que perguntando o contrário (transudato)."},{"p":"robbins","n":32,"t":"mc","tema":"inf","q":"Una niña de 9 años sufre una pequeña laceración de 0,5 cm de longitud en el dedo índice derecho mientras juega a la \"Reina de espadas\" con un abrecartas. ¿Cuál de las siguientes sustancias, al entrar en contacto con la membrana basal vascular lesionada, […]?","o":["Tromboxano","Plasmina","Factor activador de plaquetas","Factor de Hageman","Histamina"],"ok":[3],"w":["Vem das plaquetas ativadas, não do contato com a membrana basal.","Produto final da fibrinólise.","Liberado por células.","O fator XII (Hageman) se ativa ao tocar colágeno e membrana basal expostos e dispara coagulação, cininas, fibrinólise e complemento.","Vem do mastócito."],"nt":"O OCR perdeu o final do enunciado (\"se activa…\")."},{"p":"robbins","n":33,"t":"mc","tema":"inf","q":"Una mujer de 65 años ha tenido fiebre durante el último día. En el examen físico su temperatura es de 39 °C y la presión arterial de 90/50 mmHg con frecuencia cardíaca de 106/min. Los estudios de laboratorio muestran un recuento de leucocitos de 12.510/µl y un recuento diferencial de 78 segmentados, 8 bandas, 11 linfocitos y 3 monocitos. Un hemocultivo es positivo para Escherichia coli. Su presión venosa central disminuye notablemente. Entra en shock como resultado de la liberación inapropiada generalizada de un mediador químico derivado de los macrófagos. Desarrolla insuficiencia orgánica múltiple. ¿Cuál de los siguientes mediadores es más probable que produzca estos hallazgos?","o":["Óxido nítrico","Bradicinina","Histamina","Prostaciclina","Complemento C3a"],"ok":[0],"w":["Macrófagos ativados por endotoxina produzem NO em grande quantidade (iNOS): vasodilatação sistêmica, hipotensão e choque séptico.","Plasmática, não macrofágica.","Vem de mastócitos.","Vem do endotélio.","Plasmático."]},{"p":"robbins","n":35,"t":"mc","tema":"inf","q":"Una primigrávida de 24 años se encuentra en las últimas etapas del segundo trimestre de embarazo. Siente de repente un dolor abdominal bajo en forma de cólico. A esto le sigue inmediatamente la expulsión de líquido por la vagina junto con una secreción maloliente. El feto nace muerto dos días después. El examen de la placenta muestra infiltrados neutrofílicos extensos en el corion y el amnios. ¿Cuál de los siguientes organismos es más probable que sea responsable de estos hallazgos?","o":["Mycobacterium tuberculosis","Virus del herpes simple","Escherichia coli","Treponema pallidum","Toxoplasma gondii"],"ok":[2],"w":["TB dá granuloma.","Vírus dão infiltrado linfocitário.","Corioamnionite aguda com neutrófilos: bactérias ascendentes (E. coli, estreptococo do grupo B).","Sífilis dá plasmócitos e vasculite.","Toxoplasma é parasita intracelular, sem pus."]},{"p":"robbins","n":37,"t":"mc","tema":"inf","q":"Un hombre de 45 años ha tenido fiebre y tos seca durante 3 días, y ahora tiene dificultad para respirar y tos productiva de esputo. En la exploración física su temperatura es de 38,5 °C. Se auscultan estertores difusos en los campos pulmonares inferiores. Una radiografía de tórax muestra un derrame pleural derecho. Se realiza una toracocentesis derecha. El líquido obtenido tiene un aspecto turbio con un recuento celular que muestra 15.500 leucocitos por microlitro, el 98 % de los cuales son neutrófilos. ¿Cuál de los siguientes términos describe mejor su proceso pleural?","o":["Inflamación serosa","Inflamación purulenta","Inflamación fibrinosa","Inflamación crónica","Inflamación granulomatosa"],"ok":[1],"w":["Serosa é clara e pobre em células.","Turvo com 98 % de neutrófilos: exsudato purulento. Na pleura, empiema.","Fibrinosa não é turva por neutrófilos.","Crônica tem mononucleares.","Granulomatosa tem macrófagos epitelioides."]},{"p":"robbins","n":38,"t":"mc","tema":"inf","q":"Una mujer de 52 años sin problemas médicos importantes emprende un largo vuelo en avión a través del océano Pacífico. Al llegar al aeropuerto Kingsford Smith de Sídney después del vuelo desde Los Ángeles, no puede volver a ponerse los zapatos. No siente dolor ni sensibilidad. ¿Cuál de las siguientes es la explicación más probable para este fenómeno?","o":["La activación del factor de Hageman ha llevado a la producción de bradicinina","En la sección de primera clase se sirvieron muchas bebidas","Se desarrolló trombosis de la vena femoral","Le apareció celulitis en las piernas","La presión hidrostática venosa aumentó"],"ok":[4],"w":["Não há lesão vascular nem inflamação.","Brincadeira do banco; não explica edema bilateral.","Trombose dá edema unilateral e dor.","Celulite dói e fica vermelha.","Horas sentado reduzem o retorno venoso e linfático; a pressão hidrostática sobe e forma edema (transudato), sem dor."],"nt":"Edema hemodinâmico (transudato): serve para contrastar com o exsudato da inflamação."},{"p":"robbins","n":40,"t":"mc","tema":"inf","q":"Un hombre de 56 años ha tenido dificultad respiratoria cada vez mayor durante la última semana. En el examen físico no presenta fiebre. La auscultación del tórax revela disminución de los ruidos respiratorios y matidez a la percusión bilateral. Hay edemas con fóvea 2+ a la altura de los muslos. Una radiografía de tórax revela derrames pleurales bilaterales. ¿Cuál de los siguientes hallazgos de las pruebas de laboratorio es más probable que presente?","o":["Hipoalbuminemia","Glucosuria","Neutrofilia","Anemia","Hipernatremia"],"ok":[0],"w":["Albumina baixa reduz a pressão oncótica: transudato em cavidades e edema com cacifo.","Não causa edema.","Sem febre nem infecção.","Não causa derrame.","Não é a causa típica."],"nt":"Edema hemodinâmico (transudato), para contrastar com o exsudato."},{"p":"pef","n":1,"t":"mc","tema":"inf","q":"Un niño de 11 años se hace un corte en la mano al caerse. La herida se infecta. Las bacterias se expanden a la matriz extracelular alrededor de los capilares. En la respuesta inflamatoria frente a esta infección, ¿cuál de las siguientes células elimina las bacterias?","o":["Linfocito B","Fibroblasto","Macrófago","Mastocito","Linfocito T"],"ok":[2],"w":["Vira plasmócito e faz anticorpo; não fagocita.","Faz colágeno no reparo.","Fagócito \"faxineiro\" do tecido, derivado do monócito.","Libera mediadores; não fagocita.","Imunidade celular; não fagocita bactéria."]},{"p":"pef","n":2,"t":"mc","tema":"inf","q":"Una mujer de 53 años presenta fiebre alta y tos productiva con esputos amarillentos de 2 días de evolución. Sus constantes vitales son 37,8 °C de temperatura, frecuencia cardíaca de 103 latidos/min, frecuencia respiratoria de 25 respiraciones/min y presión arterial de 100/60 mmHg. En la auscultación del tórax se aprecian crepitantes en ambas bases pulmonares. La radiografía de tórax muestra infiltrados pulmonares parcheados bilaterales. La figura se corresponde con la imagen microscópica del pulmón. ¿Cuál de los siguientes tipos de células inflamatorias es más probable que se observe en abundancia en la muestra de esputo?","o":["Células gigantes de Langhans","Macrófagos","Mastocitos","Neutrófilos","Linfocitos T"],"ok":[3],"w":["Granulomatosa.","Aumentam depois, para limpar.","Alergia e anafilaxia.","Broncopneumonia bacteriana aguda: neutrófilos enchem os alvéolos e dão o escarro purulento.","Inflamação crônica."]},{"p":"pef","n":3,"t":"mc","tema":"inf","q":"Una niña de 4 años lleva 2 días con diarrea de volumen alto. En el momento de la exploración está deshidratada. La muestra de heces evaluada mediante análisis serológico es positiva para rotavirus. Recibe tratamiento con líquidos intravenosos y se recupera. ¿Cuál de los siguientes componentes está presente en las células intestinales para reconocer el ARN de doble cadena de este virus y activar los factores de transcripción que regulan al alza la producción de interferón con vistas a eliminarlo?","o":["Caspasa 1","Receptor del complemento","Lectina","Receptor de linfocitos T","Receptor de tipo señuelo (toll)"],"ok":[4],"w":["Caspase 1 é do inflamassoma (IL-1β), não reconhece RNA.","Reconhece C3b.","Lectinas reconhecem açúcares da parede microbiana.","TCR reconhece peptídeo no MHC.","TLR3 reconhece RNA de fita dupla e ativa NF-κB/IRF: interferon."]},{"p":"pef","n":4,"t":"mc","tema":"inf","q":"Un hombre de 72 años con enfisema grave ha presentado insuficiencia ventricular derecha progresiva en los últimos 5 años. Lleva 4 días con fiebre y disnea en aumento. Una radiografía de tórax muestra acumulación de líquido en los espacios pleurales. El líquido obtenido mediante toracocentesis tiene una densidad de 1,030 y contiene neutrófilos en degeneración. ¿Cuál de las siguientes es la causa más probable de esta acumulación de líquido si sufre variaciones?","o":["Presión oncótica","Diapédesis leucocítica","Presión linfática","Retención renal de sodio","Permeabilidad vascular"],"ok":[4],"w":["Pressão oncótica baixa dá transudato.","Diapedese traz células, não o líquido.","Obstrução linfática dá linfedema.","Retenção de sódio dá transudato.","Densidade 1,030 e neutrófilos: exsudato, por aumento de permeabilidade."]},{"p":"pef","n":5,"t":"mc","tema":"inf","q":"Un hombre de 35 años presenta disnea progresiva en las últimas 24 h. La radiografía de tórax muestra un derrame pleural bilateral de gran tamaño. Mediante toracocentesis se obtienen 500 ml de un líquido amarillo ligeramente turbio de la cavidad pleural derecha. El examen citológico del líquido revela múltiples neutrófilos, pero no hay linfocitos ni eritrocitos. ¿Cuál de los siguientes mecanismos contribuye más a la acumulación del líquido pleural?","o":["Vasoconstricción arteriolar","Contracción endotelial","Inhibición de la adhesión plaquetaria","Obstrucción linfática","Liberación de lisosomas por los neutrófilos"],"ok":[1],"w":["Transitória; não gera exsudato.","Mecanismo mais comum e precoce do aumento de permeabilidade.","Não tem relação.","Linfedema.","Lesa tecido, mas não é o mecanismo principal."],"nt":"Ela copiou na P2 Turma D (Q18)."},{"p":"pef","n":6,"t":"mc","tema":"inf","q":"Un niño de 6 años tiene antecedentes de infecciones de repetición por bacterias piógenas, incluidas Staphylococcus aureus y Streptococcus pneumoniae. Las infecciones se acompañan de leucocitosis con neutrofilia. El examen microscópico de una biopsia obtenida de un área de necrosis de tejido blando muestra microorganismos, pero muy pocos neutrófilos. Un análisis de la función de los neutrófilos muestra un defecto en el rodamiento. ¿Cuál de las siguientes moléculas es la causa más probable de la mayor susceptibilidad de este niño a las infecciones si sufre defectos?","o":["C3b del complemento","Integrinas","Leucotrieno B4","NADPH oxidasa","Selectinas"],"ok":[4],"w":["Opsonização.","Adesão firme.","Quimiotaxia.","Morte microbiana.","Rolamento depende de selectinas (deficiência de adesão leucocitária tipo 2)."]},{"p":"pef","n":7,"t":"mc","tema":"inf","q":"En un experimento se introducen bacterias en un preparado de tejido perfundido. Los leucocitos salen de los vasos y migran a la zona de inoculación bacteriana. ¿Cuál de las siguientes sustancias es más probable que medie el desplazamiento de esos leucocitos?","o":["Bradicinina","Quimiocinas","C3a del complemento","Histamina","Prostaglandinas"],"ok":[1],"w":["Dor e permeabilidade.","Quimiocinas (IL-8) guiam a migração.","Anafilatoxina fraca; o quimiotático é o C5a.","Permeabilidade.","Vasodilatação, dor, febre."]},{"p":"pef","n":8,"t":"mc","tema":"inf","q":"Un niño de 12 meses con infecciones de repetición en los últimos 6 meses tiene fiebre y tos de 3 días de evolución. Una tinción de Gram del esputo muestra muchos cocos grampositivos en cadenas. El hemograma revela neutrofilia. Las pruebas de laboratorio […] matan a los microorganismos rápidamente en presencia de suero […] migran normalmente en un análisis de quimiotaxinas. ¿Cuál de las siguientes causas es más probable que explique la mayor susceptibilidad del niño a las infecciones?","o":["Anomalía de la expresión de selectina","Reducción de la opsonización","Producción insuficiente de peróxido de hidrógeno por los neutrófilos","Déficit de integrinas","Defecto de las proteínas de los microtúbulos en las células fagocíticas"],"ok":[1],"w":["Migração está normal.","Os neutrófilos matam bem com soro normal: o defeito está no soro do paciente, falta opsonina.","Matam rápido, então o H2O2 está bem.","Migração normal.","Chédiak-Higashi; a migração estaria alterada."],"nt":"O OCR perdeu trechos do enunciado."},{"p":"pef","n":9,"t":"mc","tema":"inf","q":"Un niño de 5 años tiene antecedentes de infecciones bacterianas recidivantes, incluidas neumonía y otitis media. El análisis de los leucocitos recogidos de sangre periférica muestra un déficit de mieloperoxidasa. ¿Cuál de los procesos siguientes es la causa más […] cuando se reduce?","o":["Elaboración de peróxido de hidrógeno (H2O2)","Formación de radical hidroxihaluro (HOCl)","Fracaso de la migración debido a déficit del complemento","Consumo de oxígeno por las células fagocíticas","Producción de prostaglandinas"],"ok":[1],"w":["O H2O2 é feito pela NADPH oxidase, que está normal.","A mieloperoxidase transforma H2O2 + Cl⁻ em HOCl; sem ela, o hipoclorito falta.","Não há defeito de complemento.","O consumo de O2 (explosão respiratória) é da NADPH oxidase.","Não depende da MPO."],"nt":"O OCR perdeu um trecho do enunciado."},{"p":"pef","n":10,"t":"mc","tema":"inf","q":"En un experimento, se analizan los neutrófilos recogidos de sangre periférica en busca de un \"estallido\" de consumo de oxígeno. ¿En cuál de los siguientes procesos este estallido respiratorio es un paso esencial en la respuesta inflamatoria aguda?","o":["Unión a las células endoteliales","Generación de actividad microbicida","Aumento de la producción en la médula ósea","Opsonización de bacterias","Fagocitosis de bacterias"],"ok":[1],"w":["Adesão não gasta O2 em explosão.","A explosão respiratória gera EROs que matam o micróbio no fagolisossomo.","Produção medular depende de fatores estimulantes de colônias.","Opsonização é do plasma.","A fagocitose vem antes da explosão."]},{"p":"pef","n":14,"t":"mc","tema":"inf","q":"Una mujer alérgica a los gatos visita a un vecino que tiene varios de estos animales. Durante la visita, inhala epitelio de gato y a los pocos minutos desarrolla congestión nasal con secreción nasal abundante. ¿Cuál de las siguientes sustancias es más probable que provoque estos síntomas?","o":["Bradicinina","C5a del complemento","Histamina","Interleucina 1 (IL-1)","Fosfolipasa C","Factor de necrosis tumoral (TNF)"],"ok":[2],"w":["Não é da alergia.","Anafilatoxina, mas o efetor é a histamina.","Minutos depois do alérgeno: IgE no mastócito, histamina.","Febre.","Enzima de sinalização.","Citocina sistêmica."]},{"p":"pef","n":16,"t":"mc","tema":"inf","q":"Una mujer de 19 años desarrolla irritación de garganta y fiebre el día anterior. En la exploración física se observan eritema y edema faríngeo. Los hallazgos de laboratorio revelan leucocitosis. Se le administra naproxeno. ¿A cuál de los siguientes elementos de la respuesta inflamatoria aguda afecta más este fármaco?","o":["Quimiotaxia","Migración","Leucocitosis","Fagocitosis","Vasodilatación"],"ok":[4],"w":["Não depende da COX.","Não depende da COX.","Medula, citocinas.","Não depende da COX.","AINE reduz as PGs vasodilatadoras."]},{"p":"pef","n":17,"t":"mc","tema":"inf","q":"Una mujer de 35 años toma ácido acetilsalicílico para la artritis. Aunque el dolor articular disminuye con este tratamiento, el proceso inflamatorio continúa. ¿Cuál de los siguientes mediadores es el principal responsable del alivio del dolor cuando se reduce su síntesis por acción del ácido acetilsalicílico?","o":["C1q del complemento","Histamina","Leucotrieno E4","Óxido nítrico","Prostaglandinas"],"ok":[4],"w":["Complemento.","Mastócito; aspirina não mexe.","Lipoxigenase; aspirina não bloqueia.","NO sintase.","A aspirina bloqueia a COX; menos PG, menos dor."]},{"p":"pef","n":18,"t":"mc","tema":"inf","q":"Una mujer de 77 años pierde el conocimiento súbitamente, con ausencia de movimiento en la parte derecha de su organismo. La angiografía cerebral muestra una oclusión de la arteria cerebral media. ¿Cuál de los siguientes mediadores es más útil para prevenir que se agrave la lesión isquémica en la corteza cerebral?","o":["Bradicinina","Leucotrieno E4","Óxido nítrico","Factor activador de plaquetas","Tromboxano A2"],"ok":[2],"w":["Aumenta permeabilidade e edema.","Vasoconstrição.","Vasodilata e inibe a agregação plaquetária e a adesão de leucócitos.","Agrega plaquetas.","Vasoconstrição e agregação."]},{"p":"pef","n":19,"t":"mc","tema":"inf","q":"En un experimento, se inoculan bacterias en alícuotas de sangre humana normal que ha sido tratada con un anticoagulante. Se observa que las bacterias son fagocitadas por neutrófilos o bien sufren lisis. ¿Cuál de los siguientes componentes del plasma sanguíneo es más probable que facilite estos efectos?","o":["Complemento","Fibrina","Calicreína","Plasmina","Trombina"],"ok":[0],"w":["C3b opsoniza e C5b-9 lisa.","Coágulo.","Gera bradicinina.","Fibrinólise.","Coagulação."],"nt":"Ela copiou no Examen Final (Q10) e na P2 Turma D (Q9)."},{"p":"pef","n":20,"t":"mc","tema":"inf","q":"Los pacientes con daño endotelial extenso en relación con una sepsis por Escherichia coli presentan consumo de factores de la coagulación, así como una respuesta inflamatoria generalizada. ¿Cuál de las siguientes sustancias, cuya cantidad disminuye con la administración de proteína C activada, es más probable que reduzca esta respuesta inflamatoria?","o":["Complemento","Fibrina","Calicreína","Plasmina","Trombina"],"ok":[4],"w":["Não é alvo da proteína C.","Produto, não mediador inflamatório.","Via das cininas.","Fibrinólise.","A proteína C ativada inativa os fatores Va e VIIIa e reduz a trombina, que ativa receptores PAR e inflama o endotélio."]},{"p":"pef","n":21,"t":"mc","tema":"inf","q":"Una mujer de 95 años toca una olla llena de agua hirviendo. A las 2 h tiene eritema marcado en la piel de los dedos de la mano y pequeñas ampollas en las yemas de los dedos. ¿Cuál de las siguientes respuestas inflamatorias ha provocado este accidente?","o":["Inflamación fibrinosa","Inflamación granulomatosa","Inflamación purulenta","Inflamación serosa","Úlceras"],"ok":[3],"w":["Fibrina em serosas.","Crônica.","Infecção piogênica.","Bolha de queimadura: líquido seroso pobre em células.","Não há perda de epitélio."],"nt":"Ela usou a mesma ideia na recuperatória de 2023 (Q1) e na P2 da p. 97 (Q5)."},{"p":"pef","n":22,"t":"mc","tema":"nec","q":"Una mujer de 24 años sexualmente activa ha notado dolor abdominal bajo en el último día. Su temperatura es 37,9 °C y, a la palpación, la parte inferior izquierda del abdomen es muy dolorosa. Los resultados de laboratorio son leucocitos totales de 29.000/mm³ con el 75 % de neutrófilos segmentados, el 6 % de cayados, el 14 % de linfocitos y el 5 % de monocitos. La laparotomía pone de manifiesto una trompa de Falopio enrojecida, distendida y llena de líquido que está a punto de romperse. Se realiza una salpingectomía izquierda. ¿Cuál de los siguientes hallazgos es más probable observar en el examen microscópico de la trompa de Falopio resecada?","o":["Proliferación fibroblástica","Células gigantes de Langhans","Necrosis por licuefacción","Infiltrados mononucleares","Metaplasia escamosa"],"ok":[2],"w":["Reparo, mais tardio.","TB.","Infecção bacteriana aguda (piossalpinge): neutrófilos e necrose liquefativa (pus).","Crônica.","Adaptação."]},{"p":"pef","n":23,"t":"mc","tema":"inf","q":"Un hombre de 68 años presenta disnea progresiva desde hace 1 semana. En la exploración física la temperatura es de 38,3 °C. La percusión revela un tono mate en los campos pulmonares izquierdos. En la toracocentesis realizada en la cavidad pleural izquierda se obtienen 800 ml de líquido amarillento y turbio que tiene un recuento de leucocitos de 2.500/mm³ con el 98 % de neutrófilos y el 2 % de linfocitos. Una tinción de Gram del líquido muestra cocos grampositivos en racimos. ¿Cuál de los siguientes términos describe mejor el proceso que está teniendo lugar en la cavidad pleural izquierda?","o":["Absceso","Inflamación crónica","Edema","Inflamación fibrinosa","Exudado purulento","Derrame seroso"],"ok":[4],"w":["Abscesso é localizado dentro de tecido.","Teria mononucleares.","Edema é transudato.","Fibrina sem pus.","Turvo, neutrófilos e cocos: pus (empiema).","Seroso é claro."],"nt":"Ela copiou na P2 Turma D (Q17)."},{"p":"pef","n":24,"t":"mc","tema":"inf","q":"Una mujer de 87 años lleva 2 días con tos productiva y esputos amarillentos. En la exploración su temperatura es de 37 °C. La radiografía de tórax muestra infiltrados dispersos bilaterales. La sangre periférica revela leucocitosis. Una semana después no tiene fiebre. ¿Cuál de los siguientes resultados es el más probable de su enfermedad pulmonar?","o":["Inflamación crónica","Cicatrices fibrosas","Neoplasia","Resolución","Úlceras"],"ok":[3],"w":["Não há persistência.","Cicatriz se houvesse destruição da trama.","Não tem relação.","Pneumonia bacteriana tratada, com estroma preservado: resolução completa.","Não há perda de epitélio."]},{"p":"pef","n":26,"t":"mc","tema":"nec","q":"Una mujer de 92 años es diagnosticada de neumonía por Staphylococcus aureus y recibe un ciclo de tratamiento antibiótico. A las 2 semanas ya no tiene tos productiva, pero aún presenta una temperatura de 38,1 °C. La TC de tórax muestra los hallazgos de la figura. ¿Cuál de los siguientes términos describe mejor la evolución de la neumonía de la paciente?","o":["Formación de abscesos","Resolución completa","Cicatrices fibrosas","Inflamación crónica","Regeneración tisular"],"ok":[0],"w":["S. aureus e febre persistente: abscesso (necrose liquefativa).","Ainda tem febre.","Seria sem febre.","Não é a melhor descrição.","Não houve."]},{"p":"pef","n":34,"t":"mc","tema":"inf","q":"Una niña de 8 años presenta dificultades para la deglución desde el día anterior. En la exploración tiene la faringe edematosa y eritematosa con un exudado amarillo sobresaliente. Las pruebas de laboratorio muestran neutrofilia. El cultivo de la faringe identifica Streptococcus pyogenes (estreptococo del grupo A). ¿Cuál de las siguientes sustancias es más probable que aumente en respuesta a los pirógenos liberados por este microorganismo?","o":["Factor de Hageman","Inmunoglobulina E","Interleucina 12 (IL-12)","Óxido nítrico","Prostaglandinas"],"ok":[4],"w":["Coagulação e cininas.","Alergia.","Ativa Th1 e NK.","Vasodilatação.","Pirógenos (IL-1, TNF) induzem COX-2 e PGE2 no hipotálamo: febre."]},{"p":"pef","n":35,"t":"mc","tema":"inf","q":"Un hombre de 41 años sufre cefalea intensa desde hace 2 días. En la exploración la temperatura es de 39,2 °C. Se realiza una punción lumbar, y el líquido cefalorraquídeo obtenido tiene 910 leucocitos/mm³ con el 94 % de neutrófilos y el 6 % de linfocitos. ¿Cuál de las siguientes sustancias es el mediador más probable de la fiebre de este hombre?","o":["Bradicinina","Histamina","Leucotrieno B4","Óxido nítrico","Factor de necrosis tumoral (TNF)"],"ok":[4],"w":["Dor.","Vasodilatação.","Quimiotaxia.","Vasodilatação.","TNF e IL-1 são os pirógenos endógenos."]},{"p":"pef","n":36,"t":"mc","tema":"inf","q":"Un hombre de 43 años con una comunicación interventricular lleva 2 días con tos y fiebre. En la exploración su temperatura es 37,6 °C y tiene un soplo cardíaco. En un hemocultivo crece Streptococcus del grupo viridans. La velocidad de sedimentación globular (VSG) está aumentada. Las células microbianas son opsonizadas y eliminadas. ¿Cuál de los siguientes mediadores químicos es más importante en la producción de estos hallazgos?","o":["Bradicinina","Proteína C reactiva","Interferón γ","Óxido nítrico","Prostaglandina","Factor de necrosis tumoral (TNF)"],"ok":[1],"w":["Dor.","Proteína de fase aguda (feita no fígado por IL-6) que opsoniza bactérias e eleva a VSG.","Ativa macrófagos.","Vasodilatação.","Febre.","Estimula a fase aguda, mas quem opsoniza é a PCR."]}],"paginas":[{"g":"P2 · Turma C","sub":"Transcrição digitada","pages":[{"p":79,"w":1200,"h":1532},{"p":80,"w":1200,"h":1532},{"p":81,"w":1200,"h":1532},{"p":82,"w":1200,"h":1532}]},{"g":"P2 · Turma D","sub":"Folha digitada","pages":[{"p":90,"w":1200,"h":1697},{"p":91,"w":1200,"h":1697},{"p":92,"w":1200,"h":1697},{"p":93,"w":1200,"h":1697},{"p":94,"w":1200,"h":1697},{"p":95,"w":1200,"h":1697}]},{"g":"P2 · fotos","sub":"Duas provas na mesma página","pages":[{"p":97,"w":1200,"h":1696}]},{"g":"Regularización 2024","sub":"Foto, Turma C","pages":[{"p":5,"w":1200,"h":1600}]},{"g":"Recuperatoria 09/06/2023","sub":"Fotos","pages":[{"p":96,"w":1200,"h":1696},{"p":98,"w":1200,"h":1696}]},{"g":"Examen Final 21/02/2024","sub":"Fotos e transcrição","pages":[{"p":1,"w":1200,"h":1535},{"p":2,"w":1200,"h":1333},{"p":3,"w":1200,"h":1656},{"p":4,"w":1200,"h":1381},{"p":104,"w":1200,"h":1532},{"p":105,"w":1200,"h":1532},{"p":106,"w":1200,"h":1532},{"p":107,"w":1200,"h":1532},{"p":108,"w":1200,"h":1532},{"p":109,"w":1200,"h":1532},{"p":110,"w":1200,"h":1532}]},{"g":"1º Parcial","sub":"Fotos anotadas e folha digitada","pages":[{"p":8,"w":1200,"h":1751},{"p":9,"w":1200,"h":1900},{"p":10,"w":1200,"h":1759},{"p":11,"w":1200,"h":1732},{"p":12,"w":1200,"h":411},{"p":7,"w":1200,"h":1252},{"p":99,"w":1200,"h":1698},{"p":100,"w":1200,"h":1698},{"p":101,"w":1200,"h":1698},{"p":102,"w":1200,"h":1698},{"p":103,"w":1200,"h":1698}]},{"g":"1º Parcial · Recuperación","sub":"Fotos anotadas e folha digitada","pages":[{"p":16,"w":1200,"h":1737},{"p":17,"w":1200,"h":1784},{"p":18,"w":1200,"h":1752},{"p":87,"w":1200,"h":1698},{"p":88,"w":1200,"h":1698},{"p":89,"w":1200,"h":1698}]},{"g":"P1 · Turma C","sub":"Fotos anotadas e transcrição","pages":[{"p":13,"w":1200,"h":1750},{"p":14,"w":1200,"h":1809},{"p":15,"w":1200,"h":1776},{"p":83,"w":1200,"h":1698},{"p":84,"w":1200,"h":1698},{"p":85,"w":1200,"h":1698},{"p":86,"w":1200,"h":1698}]}],"orgs":[{"g":"Mapa geral","h":["<h4 class=\"mm\">Mapa da 2ª parcial</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: LESIÓN CELULAR Y RESPUESTA\"><div class=\"org-root\">LESIÓN CELULAR Y RESPUESTA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Necrosis<small>muerte celular accidental</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Lesión <b>irreversible</b></li><li>Membrana se rompe → <b>inflamación</b></li><li>Desnaturalización o digestión enzimática</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>6 patrones + ejemplo</li><li>Picnosis, cariorrexis, cariólisis</li><li>Infarto rojo × blanco</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis<small>muerte programada</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Activa, con <b>caspasas</b> y endonucleasas</li><li>Membrana íntegra → <b>sin inflamación</b></li><li>Cuerpos apoptóticos fagocitados</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>Fisiológica × patológica</li><li>Vía intrínseca (BCL2, citocromo C)</li><li>Vía extrínseca (Fas, TNFR1)</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Acumulación intracelular<small>lípidos y glucógeno</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Sustancia que la célula no metaboliza</li><li><b>Triglicéridos</b> → esteatosis</li><li><b>Colesterol</b> → aterosclerosis, xantomas</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>Células espumosas</li><li>Factores de riesgo</li><li>Complicaciones de la placa</li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Inflamación aguda<small>respuesta vascular + PMN</small></div><div class=\"org-leaf\"><h5>Qué es</h5><ul><li>Respuesta de <b>tejidos vascularizados</b></li><li>Cambios vasculares + neutrófilos</li><li>Innata, rápida, breve</li></ul></div><div class=\"org-leaf\"><h5>Cae en prueba</h5><ul><li>2 cambios vasculares</li><li>Reclutamiento de leucocitos</li><li>Patrones y mediadores</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Necrosis</span><span style=\"background:#7a3fe0\">Apoptosis</span><span style=\"background:#a16207\">Acumulación</span><span style=\"background:#0f766e\">Inflamación</span></div><div class=\"org-note\">A necrose e a acumulação de colesterol <b>disparam</b> inflamação; a apoptose não. Esse é o fio que liga os 4 temas.</div></div>"]},{"g":"Necrosis","h":["<h4 class=\"mm\">Da lesão à morte celular</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ESTÍMULO LESIVO\"><div class=\"org-root\">ESTÍMULO LESIVO</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#15803d;--cs:#dcfce7\"><div class=\"org-head\">Lesión reversible<small>se retira el estímulo → vuelve a lo normal</small></div><div class=\"org-leaf\"><h5>Cambios</h5><ul><li><b>Tumefacción celular</b> (hidrópica)</li><li><b>Cambio graso</b></li><li>Ampollas en la membrana</li><li>Mitocondrias hinchadas, RE dilatado</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Lesión irreversible<small>punto de no retorno</small></div><div class=\"org-leaf\"><h5>3 fenómenos</h5><ul><li>No recupera la <b>función mitocondrial</b></li><li>Pérdida de estructura y función de las <b>membranas</b></li><li>Pérdida de la integridad del <b>ADN y la cromatina</b></li></ul></div><div class=\"org-leaf\"><h5>Ca²⁺ intracelular activa</h5><ul><li><b>Fosfolipasas</b> → membrana</li><li><b>Proteasas</b> → citoesqueleto</li><li><b>Endonucleasas</b> → núcleo</li><li>ATPasas → menos ATP</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Necrosis<small>muerte accidental</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Siempre <b>patológica</b></li><li>Célula <b>aumenta</b> de tamaño</li><li>Rotura de membrana</li><li><b>Induce inflamación</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis<small>muerte programada</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Fisiológica o patológica</li><li>Célula se <b>encoge</b></li><li>Membrana <b>íntegra</b></li><li><b>Sin inflamación</b></li></ul></div></div></div></div>","<h4 class=\"mm\">Morfologia da necrose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: CAMBIOS MORFOLÓGICOS\"><div class=\"org-root\">CAMBIOS MORFOLÓGICOS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Microscopio óptico<small>citoplasma</small></div><div class=\"org-leaf\"><h5>Citoplasma</h5><ul><li><b>Aumento de eosinofilia</b> (pérdida de ARN, proteínas desnaturalizadas)</li><li>Aspecto vítreo, vacuolado</li><li>Figuras de mielina</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Núcleo<small>3 patrones</small></div><div class=\"org-leaf\"><h5>Picnosis</h5><ul><li>Núcleo <b>encogido</b> e hipercromático</li></ul></div><div class=\"org-leaf\"><h5>Cariorrexis</h5><ul><li>Núcleo <b>fragmentado</b></li></ul></div><div class=\"org-leaf\"><h5>Cariólisis</h5><ul><li>Basofilia nuclear <b>se desvanece</b> (ADNasa)</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Microscopio electrónico<small>irreversibilidad</small></div><div class=\"org-leaf\"><h5>Hallazgos</h5><ul><li><b>Rotura de membrana</b> plasmática y de organelas</li><li><b>Figuras de mielina</b></li><li>Densidades amorfas en mitocondrias</li></ul></div></div></div></div>","<h4 class=\"mm\">Organograma dos padrões de necrose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: NECROSIS\"><div class=\"org-root\">NECROSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Desnaturalización de proteínas<small>la arquitectura se conserva</small></div><div class=\"org-leaf\"><h5>Coagulativa</h5><ul><li><b>Isquemia</b> (excepto cerebro)</li><li>Infarto en <b>cuña</b>: IAM, riñón, bazo</li><li>Células \"fantasma\" eosinófilas</li><li>Infarto blanco</li></ul></div><div class=\"org-leaf\"><h5>Gangrena seca</h5><ul><li>Miembro sin infección</li><li>Congelación, isquemia</li><li>Patrón coagulativo</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Digestión enzimática<small>el tejido se licúa</small></div><div class=\"org-leaf\"><h5>Licuefactiva</h5><ul><li><b>Cerebro</b> (ACV, arteria cerebral media) → espacios quísticos</li><li><b>Abscesos</b>: bacterias piógenas, <i>S. aureus</i></li><li>Pus: enzimas de neutrófilos</li></ul></div><div class=\"org-leaf\"><h5>Grasa</h5><ul><li><b>Pancreatitis</b> aguda</li><li>Lipasas → ácidos grasos + Ca²⁺</li><li><b>Saponificación</b>: manchas blanco \"tiza\"</li></ul></div><div class=\"org-leaf\"><h5>Gangrena húmeda</h5><ul><li>Gangrena + <b>infección bacteriana</b></li><li>DM + pie negro + exudado</li><li>Patrón licuefactivo</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Mixta<small>coagulativa + licuefactiva</small></div><div class=\"org-leaf\"><h5>Caseosa</h5><ul><li><b>Tuberculosis</b></li><li>Aspecto de \"queso\", blanco amarillento</li><li><b>Granuloma</b>: células epitelioides, gigantes de <b>Langhans</b>, linfocitos</li><li>MO: material amorfo, granular, rosado</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Vascular inmune<small>pared de los vasos</small></div><div class=\"org-leaf\"><h5>Fibrinoide</h5><ul><li>Complejos Ag-Ac + fibrina en la pared</li><li><b>LES</b>, vasculitis, PAN</li><li>HTA maligna</li><li>Nódulo reumatoide</li></ul></div><div class=\"org-leaf\"><h5>Calcificación distrófica</h5><ul><li>Ca²⁺ en tejido <b>necrótico</b></li><li>Calcemia <b>normal</b></li><li>Placas de ateroma, válvulas</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Desnaturalización: coagulativa, gangrena seca</span><span style=\"background:#c2410c\">Digestión: licuefactiva, grasa, gangrena húmeda</span></div><div class=\"org-note\">Pergunta clássica dela: <b>cite 2 por desnaturalização</b> (coagulativa e gangrena seca) e <b>2 por digestão enzimática</b> (licuefativa e grasa).</div></div>","<h4 class=\"mm\">Infarto rojo × blanco</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: INFARTO\"><div class=\"org-root\">INFARTO</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Infarto blanco<small>anémico</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Oclusión <b>arterial</b></li><li>Órganos <b>sólidos</b> con circulación terminal</li><li><b>Corazón, bazo, riñón</b></li><li>Forma de cuña · necrosis coagulativa</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Infarto rojo<small>hemorrágico</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Oclusión <b>venosa</b> (torsión ovárica, testicular)</li><li>Tejidos <b>laxos</b></li><li><b>Doble circulación</b>: pulmón, hígado</li><li>Intestino; <b>reperfusión</b>; congestión previa</li></ul></div></div></div></div>"]},{"g":"Apoptosis","h":["<h4 class=\"mm\">Quando ocorre a apoptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: APOPTOSIS\"><div class=\"org-root\">APOPTOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#15803d;--cs:#dcfce7\"><div class=\"org-head\">Fisiológica<small>elimina células que ya no se necesitan</small></div><div class=\"org-leaf\"><h5>Embriogénesis</h5><ul><li><b>Membranas interdigitales</b></li><li>Organogénesis, involución de primordios</li></ul></div><div class=\"org-leaf\"><h5>Involución hormonal</h5><ul><li><b>Ciclo menstrual</b> (endometrio)</li><li><b>Menopausia</b> (atresia folicular)</li><li>Mama tras el <b>destete</b></li></ul></div><div class=\"org-leaf\"><h5>Recambio y defensa</h5><ul><li>Recambio de poblaciones proliferativas</li><li>Neutrófilos al final de la inflamación</li><li>Linfocitos <b>autorreactivos</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Patológica<small>células dañadas sin reparación</small></div><div class=\"org-leaf\"><h5>Daño del ADN</h5><ul><li>Radiación, quimioterapia</li><li>p53 detiene el ciclo o induce apoptosis</li></ul></div><div class=\"org-leaf\"><h5>Proteínas mal plegadas</h5><ul><li>Estrés del RE</li><li><b>Alzheimer, Parkinson</b></li></ul></div><div class=\"org-leaf\"><h5>Infecciones</h5><ul><li><b>Hepatitis viral</b> (cuerpos de Councilman)</li><li>Linfocitos T citotóxicos</li></ul></div><div class=\"org-leaf\"><h5>Atrofia patológica</h5><ul><li><b>Obstrucción de conductos</b>: páncreas, parótida, riñón</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#15803d\">Fisiológica</span><span style=\"background:#b3141c\">Patológica</span></div></div>","<h4 class=\"mm\">Organograma das vias da apoptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: APOPTOSIS · ENZIMAS: CASPASAS Y ENDONUCLEASAS\"><div class=\"org-root\">APOPTOSIS · ENZIMAS: CASPASAS Y ENDONUCLEASAS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Vía intrínseca<small>mitocondrial · la más frecuente</small></div><div class=\"org-leaf\"><h5>Familia BCL2</h5><ul><li><b>Antiapoptóticas</b>: BCL2, BCLX, MCL1</li><li><b>Proapoptóticas</b>: BAX, BAK</li><li>Sensores BH3: BAD, BIM, BID</li></ul></div><div class=\"org-leaf\"><h5>Secuencia</h5><ul><li>Estrés: falta de factores de crecimiento, daño del ADN</li><li>BAX/BAK abren la membrana mitocondrial</li><li><b>Citocromo C sale al citosol</b></li><li>Apoptosoma → <b>caspasa 9</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Vía extrínseca<small>receptores de muerte</small></div><div class=\"org-leaf\"><h5>Receptores</h5><ul><li><b>TNFR1</b> (receptor de TNF tipo 1)</li><li><b>Fas (CD95)</b> + FasL</li></ul></div><div class=\"org-leaf\"><h5>Secuencia</h5><ul><li>Dominio de muerte → FADD</li><li><b>Caspasa 8</b></li><li>Inhibidor: FLIP</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Fase de ejecución<small>converge</small></div><div class=\"org-leaf\"><h5>Ejecutoras</h5><ul><li><b>Caspasas 3 y 6</b></li><li><b>Endonucleasas</b> fragmentan el ADN</li><li>Proteasas degradan citoesqueleto</li></ul></div><div class=\"org-leaf\"><h5>Final</h5><ul><li><b>Cuerpos apoptóticos</b></li><li>Fosfatidilserina expuesta → fagocitosis</li><li><b>Sin inflamación</b></li></ul></div></div></div><div class=\"org-note\">Citocromo C <b>não</b> é enzima: é a proteína que sai da mitocôndria e ativa o apoptossoma. As 2 enzimas são <b>caspasas y endonucleasas</b>.</div></div>","<h4 class=\"mm\">Necrose × apoptose × necroptose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: MUERTE CELULAR\"><div class=\"org-root\">MUERTE CELULAR</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Necrosis</div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Célula <b>aumentada</b></li><li>Picnosis → cariorrexis → cariólisis</li><li>Membrana <b>rota</b></li><li>Contenido sale → <b>inflamación</b></li><li>Siempre patológica</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Apoptosis</div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Célula <b>reducida</b></li><li>Fragmentación en nucleosomas</li><li>Membrana <b>íntegra</b></li><li>Cuerpos apoptóticos, <b>sin inflamación</b></li><li>Fisiológica o patológica</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Necroptosis<small>híbrida</small></div><div class=\"org-leaf\"><h5>Rasgos</h5><ul><li>Programada como la apoptosis</li><li>Morfología de <b>necrosis</b></li><li><b>Sin caspasas</b></li><li>RIPK1, RIPK3, MLKL</li></ul></div></div></div></div>"]},{"g":"Acumulación: lípidos","h":["<h4 class=\"mm\">Organograma das acumulações</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ACUMULACIONES INTRACELULARES\"><div class=\"org-root\">ACUMULACIONES INTRACELULARES</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Lípidos<small>slide da professora</small></div><div class=\"org-leaf\"><h5>Triglicéridos</h5><ul><li><b>Esteatosis</b> (só citada no slide novo)</li><li>Hígado, corazón, músculo, riñón</li><li>Sudán / aceite rojo O</li></ul></div><div class=\"org-leaf\"><h5>Colesterol y ésteres</h5><ul><li><b>Aterosclerosis</b>: células espumosas</li><li><b>Xantomas</b></li><li><b>Colesterolosis</b> (vesícula en fresa)</li><li><b>Niemann-Pick tipo C</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Glucógeno<small>slide antigo · baixa prioridade</small></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li><b>Diabetes mellitus</b>: túbulos renales, hepatocitos, islotes</li><li><b>Glucogenosis</b> (enzimopatías)</li><li>Vacuolas claras</li><li><b>PAS</b> / carmín de <b>Best</b>: rosa-violáceo</li></ul></div></div><div class=\"org-col\" style=\"--c:#a21caf;--cs:#fae8ff\"><div class=\"org-head\">Clase 7<small>tema 04 desta apostila</small></div><div class=\"org-leaf\"><h5>Otras acumulaciones</h5><ul><li><b>Proteínas</b>: gotículas eosinófilas, Russell, Mallory, Lewy</li><li><b>Amiloidosis</b> (extracelular)</li><li><b>Calcificación</b> distrófica × metastásica</li></ul></div></div></div></div>","<h4 class=\"mm\">Esteatose: causa, mecanismo, aspecto</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ESTEATOSIS\"><div class=\"org-root\">ESTEATOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Causas</div><div class=\"org-leaf\"><h5>Principales</h5><ul><li><b>Alcohol</b> (la más frecuente)</li><li><b>Diabetes</b> / síndrome metabólico</li><li><b>Obesidad</b></li><li>Toxinas, desnutrición proteica, hipoxia</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Mecanismo<small>6 pasos del metabolismo</small></div><div class=\"org-leaf\"><h5>Fallas posibles</h5><ul><li>↑ Entrada de ácidos grasos</li><li>↑ Síntesis o ↓ oxidación</li><li>↓ Apoproteínas</li><li>↓ Secreción de lipoproteínas</li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Morfología</div><div class=\"org-leaf\"><h5>Aspecto</h5><ul><li>Macro: hígado <b>grande, amarillo, graso</b></li><li>Micro: <b>vacuolas claras</b> que desplazan el núcleo</li><li>Micro/macrovesicular</li><li>Tinción: <b>Sudán IV, aceite rojo O</b></li></ul></div></div></div></div>","<h4 class=\"mm\">Organograma da aterosclerose</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: ATEROSCLEROSIS\"><div class=\"org-root\">ATEROSCLEROSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Factores de riesgo</div><div class=\"org-leaf\"><h5>No modificables</h5><ul><li><b>Edad</b></li><li><b>Sexo masculino</b></li><li><b>Antecedentes familiares</b></li><li>Genética</li></ul></div><div class=\"org-leaf\"><h5>Modificables</h5><ul><li><b>Hipercolesterolemia</b> (LDL ↑, HDL ↓)</li><li><b>HTA</b></li><li><b>Tabaco</b></li><li><b>DM</b> / síndrome metabólico</li><li>PCR (inflamación)</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Respuesta a la lesión<small>patogenia</small></div><div class=\"org-leaf\"><h5>Pasos</h5><ul><li>1. Lesión / disfunción <b>endotelial</b></li><li>2. Entrada y oxidación de <b>LDL</b></li><li>3. Adhesión de monocitos → <b>macrófagos</b></li><li>4. <b>Células espumosas</b> (macrófagos + CML)</li><li>5. Migración y proliferación de <b>CML</b></li><li>6. Matriz extracelular: <b>placa</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Placa<small>túnica íntima</small></div><div class=\"org-leaf\"><h5>Componentes</h5><ul><li><b>Capa fibrosa</b> (CML, colágeno)</li><li><b>Núcleo necrótico</b>: lípidos, restos, células espumosas</li><li>Hombro: macrófagos, linfocitos T</li></ul></div><div class=\"org-leaf\"><h5>Estable × vulnerable</h5><ul><li>Estable: capa <b>gruesa</b>, poco lípido</li><li>Vulnerable: capa <b>fina</b>, mucho lípido e inflamación</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Complicaciones<small>cambios agudos</small></div><div class=\"org-leaf\"><h5>De la placa</h5><ul><li><b>Rotura, ulceración, erosión</b> → trombosis</li><li><b>Hemorragia</b> intraplaca</li><li><b>Ateroembolia</b></li><li><b>Calcificación distrófica</b></li></ul></div><div class=\"org-leaf\"><h5>Del vaso</h5><ul><li><b>Aneurisma</b> (debilita la media)</li><li>Estenosis → isquemia</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Riesgo</span><span style=\"background:#c2410c\">Patogenia</span><span style=\"background:#a16207\">Placa</span><span style=\"background:#4338ca\">Complicaciones</span></div></div>"]},{"g":"Proteínas, amiloide, calcio (Clase 7)","h":["<h4 class=\"mm\">Organograma: acumulação de proteínas</h4><div aria-label=\"Organograma: PROTEÍNAS · gotículas eosinófilas\" class=\"org\" role=\"img\"><div class=\"org-root\">PROTEÍNAS · gotículas eosinófilas</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:5\"><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Reabsorción tubular<small>riñón</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proteinuria → túbulo proximal reabsorbe más por <b>pinocitosis</b></li><li><b>Gotículas hialinas rosadas</b></li><li><b>REVERSIBLE</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Inmunoglobulinas<small>célula plasmática</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Exceso de Ig distiende el RE</li><li><b>Cuerpos de Russell</b></li><li>Inclusiones eosinófilas homogéneas</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Transporte defectuoso<small>plegamiento lento</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>Deficiencia de α1-antitripsina</b></li><li>Glóbulos eosinófilos en el RE del <b>hepatocito</b> (PAS +)</li><li>Pulmón sin enzima → <b>ENFISEMA</b></li><li>Estrés del RE → apoptosis</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Citoesqueleto<small>filamentos intermedios</small></div><div class=\"org-leaf\"><h5>Queratina</h5><ul><li><b>Hialina alcohólica / de Mallory</b></li><li>Hepatopatía alcohólica</li></ul></div><div class=\"org-leaf\"><h5>Neurofilamentos</h5><ul><li><b>Ovillos neurofibrilares</b></li><li>Alzheimer · tinción de plata</li></ul></div><div class=\"org-leaf\"><h5>α-sinucleína</h5><ul><li><b>Cuerpos de Lewy</b></li><li>Demencia de cuerpos de Lewy · IHQ ubiquitina</li></ul></div></div><div class=\"org-col\" style=\"--c:#7a3fe0;--cs:#f3eefe\"><div class=\"org-head\">Agregación anómala<small>proteinopatías</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proteínas <b>mal plegadas</b></li><li>Depósitos IC, EC o ambos</li><li><b>AMILOIDOSIS</b>: fibrillas insolubles extracelulares</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#0f766e\">1 Riñón</span><span style=\"background:#4338ca\">2 Ig</span><span style=\"background:#a16207\">3 α1-AT</span><span style=\"background:#b3141c\">4 Citoesqueleto</span><span style=\"background:#7a3fe0\">5 Amiloide</span></div></div>","<h4 class=\"mm\">Organograma da amiloidose</h4><div aria-label=\"Organograma: AMILOIDOSIS\" class=\"org\" role=\"img\"><div class=\"org-root\">AMILOIDOSIS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Primaria<small>sistémica · AL</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Proliferación <b>clonal</b> de células plasmáticas</li><li>Ig anómala: <b>cadena ligera (AL)</b></li><li><b>Mieloma múltiple</b></li><li>Órganos: <b>corazón</b>, tubo digestivo, vías respiratorias, nervios periféricos, piel, <b>lengua</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Secundaria reactiva<small>sistémica · AA</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Complicación de <b>inflamación crónica</b></li><li>Proteína <b>AA</b> (asociada a amiloide)</li><li><b>Artritis reumatoide</b>, <b>EII</b> (Crohn, colitis ulcerosa)</li><li>Órganos: <b>riñón</b>, hígado, bazo, ganglios, suprarrenales, tiroides</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">β-amiloide<small>localizada</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>Enfermedad de Alzheimer</b></li><li>Placas cerebrales</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Otras</div><div class=\"org-leaf\"><h5>Lista del slide</h5><ul><li>Hereditaria o familiar</li><li><b>Hemodiálisis</b>: microglobulina β2 → <b>túnel carpiano</b></li><li><b>Endocrina</b>: tumores tiroideos, pancreáticos, feocromocitoma</li><li><b>Senil</b>: corazón</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#4338ca\">3 formas más frecuentes: AL · AA · β</span></div><div class=\"org-note\">Rim: o mais frequente e o mais grave. Coração: o principal órgão na amiloidose <b>senil</b>.</div></div>","<h4 class=\"mm\">Organograma da calcificação patológica</h4><div aria-label=\"Organograma: CALCIFICACIÓN PATOLÓGICA\" class=\"org\" role=\"img\"><div class=\"org-root\">CALCIFICACIÓN PATOLÓGICA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Distrófica<small>tejido muerto o lesionado</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Calcemia <b>NORMAL</b></li><li>Generalmente <b>IRREVERSIBLE</b></li><li>Necrosis (todas), <b>ateromas</b>, válvulas dañadas o de ancianos, trombos, hematomas, tumores, <b>Mönckeberg</b></li></ul></div><div class=\"org-leaf\"><h5>Patogenia</h5><ul><li>Proteína desnaturalizada + fosfato + Ca²⁺ → fosfato de calcio</li><li><b>Iniciación</b>: mitocondrias o vesículas</li><li><b>Propagación</b>: cristales</li></ul></div><div class=\"org-leaf\"><h5>Morfología</h5><ul><li>Macro: <b>\"depósitos arenosos\"</b> blanquecinos</li><li>H&amp;E: <b>basófilo</b>, granular, amorfo</li><li>Hueso heterotópico con el tiempo</li><li><b>Cuerpos de psamoma</b> (cáncer papilar)</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Metastásica<small>tejido normal</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li><b>HIPERCALCEMIA</b> siempre</li><li><b>REVERSIBLE</b> si se corrige la causa</li><li>En general sin disfunción clínica</li></ul></div><div class=\"org-leaf\"><h5>4 causas</h5><ul><li>↑ <b>PTH</b> (hiperparatiroidismo)</li><li><b>Resorción ósea</b>: mieloma, metástasis, inmovilización</li><li>Trastornos de <b>vitamina D</b></li><li><b>Insuficiencia renal crónica</b></li><li>(+ síndrome leche-alcalinos)</li></ul></div><div class=\"org-leaf\"><h5>Dónde</h5><ul><li>Mucosa <b>gástrica</b>, <b>riñones</b>, <b>pulmones</b></li><li>Arterias sistémicas, venas pulmonares, sinovial</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Distrófica: Ca normal</span><span style=\"background:#4338ca\">Metastásica: Ca alto</span></div></div>"]},{"g":"Inflamación aguda","h":["<h4 class=\"mm\">Aguda × crônica</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: INFLAMACIÓN \"ITIS\"\"><div class=\"org-root\">INFLAMACIÓN \"ITIS\"</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Inflamación aguda<small>inmunidad innata</small></div><div class=\"org-leaf\"><h5>Tiempo</h5><ul><li>Minutos u horas</li><li>Duración breve</li><li>Resolución espontánea</li></ul></div><div class=\"org-leaf\"><h5>2 características</h5><ul><li><b>Cambios vasculares</b>: vasodilatación + ↑ permeabilidad → exudado (edema)</li><li>Infiltrado de <b>polimorfonucleares (neutrófilos)</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Inflamación crónica<small>inmunidad adaptativa</small></div><div class=\"org-leaf\"><h5>Tiempo</h5><ul><li>Meses o años</li><li>Mayor destrucción tisular</li></ul></div><div class=\"org-leaf\"><h5>2 características</h5><ul><li><b>Proliferación de vasos</b> (angiogénesis) + <b>tejido conjuntivo</b> (colágeno)</li><li><b>Mononucleares</b>: linfocitos, macrófagos, plasmáticas</li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Causas<small>de ambas</small></div><div class=\"org-leaf\"><h5>Lista</h5><ul><li>Infecciones</li><li>Necrosis tisular</li><li>Cuerpos extraños (astillas, suturas, colesterol)</li><li>Reacciones inmunitarias (TB = hipersensibilidad IV)</li></ul></div></div></div></div>","<h4 class=\"mm\">Organograma da inflamação aguda</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: INFLAMACIÓN AGUDA · 3 COMPONENTES\"><div class=\"org-root\">INFLAMACIÓN AGUDA · 3 COMPONENTES</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">1 · Calibre y flujo<small>vasodilatación</small></div><div class=\"org-leaf\"><h5>Secuencia</h5><ul><li><b>Vasoconstricción transitoria</b> (segundos, no característica)</li><li><b>Vasodilatación arteriolar</b> (histamina de mastocitos)</li><li>Apertura de nuevos lechos capilares</li><li>↑ volumen, ↓ velocidad → <b>estasis</b></li></ul></div><div class=\"org-leaf\"><h5>Signos</h5><ul><li><b>Rubor</b> (eritema)</li><li><b>Calor</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">2 · Permeabilidad<small>vénulas poscapilares</small></div><div class=\"org-leaf\"><h5>Mecanismos</h5><ul><li><b>Contracción de células endoteliales</b> (más frecuente)</li><li><b>Lesión endotelial</b></li><li><b>Transcitosis</b> (VEGF)</li></ul></div><div class=\"org-leaf\"><h5>Resultado</h5><ul><li>Exudado rico en proteínas y células</li><li><b>Edema</b> → <b>tumor</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">3 · Migración de leucocitos<small>reclutamiento</small></div><div class=\"org-leaf\"><h5>En la luz</h5><ul><li><b>Marginación</b></li><li><b>Rodamiento</b> → selectinas</li><li><b>Adhesión</b> → integrinas</li></ul></div><div class=\"org-leaf\"><h5>A través de la pared</h5><ul><li><b>Transmigración / diapédesis</b> → inmunoglobulinas (PECAM-1)</li></ul></div><div class=\"org-leaf\"><h5>En el tejido</h5><ul><li><b>Quimiotaxia</b>: IL-8, C5a, LTB4</li><li><b>Fagocitosis</b>: ERO, óxido nítrico, enzimas lisosómicas</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Vasodilatación</span><span style=\"background:#c2410c\">Permeabilidad</span><span style=\"background:#0f766e\">Leucocitos</span></div></div>","<h4 class=\"mm\">Exsudato × transudato</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: EDEMA (exceso de líquido)\"><div class=\"org-root\">EDEMA (exceso de líquido)</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:2\"><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Trasudado<small>ultrafiltrado de plasma</small></div><div class=\"org-leaf\"><h5>Características</h5><ul><li>Proteínas <b>bajas</b>, pocas células</li><li>Densidad <b>baja</b>, aspecto claro</li><li>Mecanismo: <b>presión hidrostática u osmótica</b></li><li>Ej.: insuficiencia cardíaca, hipoalbuminemia</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Exudado<small>inflamatorio</small></div><div class=\"org-leaf\"><h5>Características</h5><ul><li>Proteínas <b>altas</b>, muchas células</li><li>Densidad <b>alta</b>, aspecto <b>turbio</b></li><li>Mecanismo: <b>↑ permeabilidad vascular</b></li><li>Ej.: neumonía, pus</li></ul></div><div class=\"org-leaf\"><h5>Pus</h5><ul><li>Exudado <b>purulento</b></li><li>Neutrófilos + restos necróticos + microbios</li></ul></div></div></div></div>","<h4 class=\"mm\">Trajeto do leucócito, passo a passo</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: RECLUTAMIENTO DE LEUCOCITOS\"><div class=\"org-root\">RECLUTAMIENTO DE LEUCOCITOS</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Luz vascular<small>3 pasos</small></div><div class=\"org-leaf\"><h5>1. Marginación</h5><ul><li>Redistribución hacia la periferia</li><li>Depende de la <b>estasis</b></li></ul></div><div class=\"org-leaf\"><h5>2. Rodamiento</h5><ul><li>Adherencia <b>débil, transitoria</b></li><li><b>Selectinas</b> (E, P)</li></ul></div><div class=\"org-leaf\"><h5>3. Adhesión</h5><ul><li>Adherencia <b>firme</b></li><li><b>Integrinas</b> (β2), activadas por quimiocinas</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Pared vascular<small>1 paso</small></div><div class=\"org-leaf\"><h5>4. Transmigración</h5><ul><li>= <b>diapédesis</b> = migración</li><li><b>Vénulas poscapilares</b></li><li>Espacios interendoteliales</li><li><b>Inmunoglobulinas</b> (PECAM-1/CD31)</li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Tejido<small>2 pasos</small></div><div class=\"org-leaf\"><h5>5. Quimiotaxia</h5><ul><li>Desplazamiento <b>por los tejidos</b> hacia la lesión</li><li>Exógenos: productos bacterianos</li><li>Endógenos: <b>interleucina 8, C5a, leucotrieno B4</b></li></ul></div><div class=\"org-leaf\"><h5>6. Fagocitosis</h5><ul><li>Reconocimiento y fijación</li><li>Atrapamiento → <b>fagolisosoma</b></li><li>Destrucción: <b>especies reactivas de oxígeno, óxido nítrico, enzimas lisosómicas</b></li></ul></div></div></div><div class=\"org-note\">Marginación ≠ migración. Migración = atravessar o endotélio; quimiotaxia = andar pelo tecido.</div></div>","<h4 class=\"mm\">Organograma dos padrões morfológicos</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: PATRONES DE INFLAMACIÓN AGUDA\"><div class=\"org-root\">PATRONES DE INFLAMACIÓN AGUDA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:4\"><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Serosa<small>líquido pobre en células</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Exudación tipo <b>trasudado</b></li><li>Sin microorganismos</li><li><b>Ampollas</b> (quemadura, fricción)</li><li>Infecciones virales</li><li>Cavidades: pleura, pericardio, peritoneo</li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Fibrinosa<small>permeabilidad mayor</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Sale <b>fibrinógeno</b> → fibrina</li><li>MO: red <b>eosinófila</b></li><li>Meninges, pericardio, pleura</li><li><b>Pericarditis en pan con mantequilla</b></li><li>Si persiste: organización → cicatriz</li></ul></div></div><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Purulenta / supurativa<small>pus</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Neutrófilos + necrosis licuefactiva</li><li>Bacterias <b>piógenas</b>: <i>S. aureus</i></li><li><b>Apendicitis aguda</b></li></ul></div><div class=\"org-leaf\"><h5>Absceso</h5><ul><li>Colección <b>localizada</b> de pus</li><li>Pared fibrosa con el tiempo</li><li>Rx: <b>nivel hidroaéreo</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#475569;--cs:#f1f5f9\"><div class=\"org-head\">Úlcera<small>defecto de superficie</small></div><div class=\"org-leaf\"><h5>Claves</h5><ul><li>Excavación, <b>solución de continuidad</b></li><li>Mucosa digestiva, genitourinaria, piel</li><li>Úlcera péptica, pie diabético</li><li><b>Coexisten aguda y crónica</b></li></ul></div></div></div></div>","<h4 class=\"mm\">Evolução da inflamação aguda</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: INFLAMACIÓN AGUDA\"><div class=\"org-root\">INFLAMACIÓN AGUDA</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#15803d;--cs:#dcfce7\"><div class=\"org-head\">Resolución completa<small>remisión</small></div><div class=\"org-leaf\"><h5>Cuándo</h5><ul><li>Lesión limitada y breve</li><li>Poca destrucción</li><li>Tejido capaz de <b>regenerar</b></li></ul></div></div><div class=\"org-col\" style=\"--c:#a16207;--cs:#fef3c7\"><div class=\"org-head\">Cicatrización / fibrosis<small>tejido conjuntivo</small></div><div class=\"org-leaf\"><h5>Cuándo</h5><ul><li>Destrucción <b>extensa</b></li><li>Tejido que no regenera</li><li>Mucha <b>fibrina</b> (organización)</li><li>Absceso</li></ul></div></div><div class=\"org-col\" style=\"--c:#4338ca;--cs:#e0e7ff\"><div class=\"org-head\">Inflamación crónica<small>progresión</small></div><div class=\"org-leaf\"><h5>Cuándo</h5><ul><li>El agente <b>persiste</b></li><li>Alteración de la curación</li></ul></div></div></div><div class=\"org-note\">Depende de: naturaleza e intensidade da lesão, tecido afetado e resposta do hospedeiro.</div></div>","<h4 class=\"mm\">Organograma dos mediadores</h4><div class=\"org\" role=\"img\" aria-label=\"Organograma: MEDIADORES DE LA INFLAMACIÓN\"><div class=\"org-root\">MEDIADORES DE LA INFLAMACIÓN</div><div class=\"org-stem\"></div><div class=\"org-cols\" style=\"--n:3\"><div class=\"org-col\" style=\"--c:#b3141c;--cs:#fde7e9\"><div class=\"org-head\">Derivados de células<small>preformados (gránulos)</small></div><div class=\"org-leaf\"><h5>Aminas vasoactivas</h5><ul><li><b>Histamina</b> (mastocitos): vasodilatación + permeabilidad</li><li><b>Serotonina</b>: <u>solo</u> permeabilidad</li></ul></div><div class=\"org-leaf\"><h5>Enzimas lisosomales</h5><ul><li>Lesión tisular, destrucción en la fagocitosis</li></ul></div></div><div class=\"org-col\" style=\"--c:#c2410c;--cs:#ffedd5\"><div class=\"org-head\">Derivados de células<small>sintetizados de novo</small></div><div class=\"org-leaf\"><h5>Prostaglandinas</h5><ul><li>Vasodilatación, <b>dolor</b>, <b>fiebre</b></li><li>Vía ciclooxigenasa (AINE)</li></ul></div><div class=\"org-leaf\"><h5>Leucotrienos</h5><ul><li><b>LTB4</b>: quimiotaxia</li><li><b>LTC4, D4, E4</b>: permeabilidad (\"CDE\")</li></ul></div><div class=\"org-leaf\"><h5>Citocinas</h5><ul><li><b>TNF, IL-1</b>: reclutamiento, fiebre</li><li><b>IL-6</b>: fiebre</li><li><b>IL-8</b>: quimiotáctica</li></ul></div></div><div class=\"org-col\" style=\"--c:#0f766e;--cs:#ccfbf1\"><div class=\"org-head\">Derivados del plasma<small>precursores inactivos, hígado</small></div><div class=\"org-leaf\"><h5>Complemento</h5><ul><li><b>C3a, C5a</b>: anafilotoxinas</li><li><b>C5a</b>: quimiotaxia</li><li><b>C3b</b>: opsonina</li><li><b>C5b-9</b>: MAC, lisis</li></ul></div><div class=\"org-leaf\"><h5>Cininas</h5><ul><li><b>Bradicinina</b>: permeabilidad, vasodilatación, <b>dolor</b></li></ul></div><div class=\"org-leaf\"><h5>Coagulación</h5><ul><li>Poca importancia para ella</li></ul></div></div></div><div class=\"org-key\"><span style=\"background:#b3141c\">Preformados</span><span style=\"background:#c2410c\">Sintetizados</span><span style=\"background:#0f766e\">Plasma</span></div><div class=\"org-note\">Ela pergunta <b>origem e função</b>. Bradicinina <b>não</b> é derivada de célula.</div></div>"]}]};
